"""
ABHA at the registration desk: find a person's ABHA by Aadhaar number, mobile
number, ABHA number or ABHA address, create one by Aadhaar OTP when a lookup
by Aadhaar finds none, and link the verified ABHA to a CARE patient.

A journey is an `AbhaTransaction` kept on the server. The browser holds its
id and is told the step it is on and what the screen should show; ABDM's
transaction ids and tokens stay here.
"""

import logging
from contextlib import contextmanager

from django.conf import settings
from django.http import HttpResponse
from pydantic import ValidationError
from rest_framework.decorators import action
from rest_framework.exceptions import PermissionDenied
from rest_framework.response import Response
from rest_framework.viewsets import GenericViewSet

from care.abdm import abha
from care.abdm.api.specs import (
    AddressCreateRequest,
    AddressSearchRequest,
    EnrolVerifyRequest,
    LinkRequest,
    LoginSendOtpRequest,
    OtpVerifyRequest,
    TransactionRequest,
    VerifyUserRequest,
)
from care.abdm.client import GATEWAY_TOKEN_ERROR_CODES, AbdmError, encrypt
from care.abdm.identifiers import (
    AbhaLinkError,
    find_linked_patient,
    link_abha_to_patient,
)
from care.abdm.models import AbhaConsent
from care.abdm.transaction import AbhaTransaction
from care.emr.api.viewsets.base import emr_exception_handler
from care.emr.models.organization import FacilityOrganizationUser
from care.emr.models.patient import Patient
from care.facility.models.facility import Facility
from care.security.authorization import AuthorizationController
from care.utils.shortcuts import get_object_or_404

logger = logging.getLogger(__name__)

# The only answers that mean nobody holds an ABHA for what was entered:
# ABDM-1114 for the Aadhaar, mobile and ABHA number lookups, ABDM-1211 for an
# ABHA address. Any other refusal is shown as it is, never as "not found".
NOT_FOUND_CODES = {"ABDM-1114", "ABDM-1211"}

# Steps waiting for an OTP, and whose OTP it is.
OTP_STEPS = {"login": "login", "enrol": "enrol", "mobile_otp": "mobile"}

# ABDM's names for request fields, as the desk's form names them.
FIELD_NAMES = {
    "otpValue": "otp",
    "otp": "otp",
    "loginId": "value",
    "value": "value",
    "mobile": "mobile",
    "abhaAddress": "abha_address",
    "abha_address": "abha_address",
    "ABHANumber": "account",
    "account": "account",
}

GATEWAY_AUTH_MESSAGE = "Could not authenticate with ABDM. Please try again."
ABHA_NUMBER_LENGTH = 14


class JourneyError(Exception):
    """A request the journey refuses on its own, before or instead of ABDM."""

    def __init__(self, error_type, message, *, field=None, status=400, **extra):
        super().__init__(message)
        self.error_type = error_type
        self.message = message
        self.field = field
        self.status = status
        self.extra = extra


def _abdm_status(exc: AbdmError) -> int:
    if exc.status == 429:  # noqa: PLR2004
        return 429
    if exc.status == 401 and exc.code in GATEWAY_TOKEN_ERROR_CODES:  # noqa: PLR2004
        return 502
    if 400 <= exc.status < 500:  # noqa: PLR2004
        return 400
    if exc.status == 502:  # noqa: PLR2004
        return 502
    return 503


def _error(error_type, message, field=None, **extra) -> dict:
    error = {"type": error_type, "msg": message, **extra}
    if field:
        error["loc"] = [field]
    return error


def patient_summary(patient: Patient | None) -> dict | None:
    if not patient:
        return None
    return {"id": str(patient.external_id), "name": patient.name}


def abdm_exception_handler(exc, context):
    if isinstance(exc, AbdmError):
        status = _abdm_status(exc)
        gateway_auth = exc.status == 401 and exc.code in GATEWAY_TOKEN_ERROR_CODES  # noqa: PLR2004
        message = GATEWAY_AUTH_MESSAGE if gateway_auth else exc.message
        field = FIELD_NAMES.get(exc.field) if status == 400 else None  # noqa: PLR2004
        error = _error(
            "abdm_error", message, field, code=exc.code, request_id=exc.request_id
        )
        return Response({"errors": [error]}, status=status)
    if isinstance(exc, JourneyError):
        error = _error(exc.error_type, exc.message, exc.field, **exc.extra)
        return Response({"errors": [error]}, status=exc.status)
    if isinstance(exc, AbhaLinkError):
        error = _error(
            exc.error_type, exc.message, patient=patient_summary(exc.patient)
        )
        return Response({"errors": [error]}, status=400)
    if isinstance(exc, ValidationError):
        # The submitted values are not echoed back: they are Aadhaar numbers,
        # mobiles and OTPs.
        errors = [
            _error(
                "validation_error",
                error["msg"].removeprefix("Value error, "),
                ".".join(str(part) for part in error["loc"]) or None,
            )
            for error in exc.errors(include_url=False, include_input=False)
        ]
        return Response({"errors": errors}, status=400)
    return emr_exception_handler(exc, context)


@contextmanager
def default_field(name: str):
    """Attribute a refusal that names no field to the field just submitted."""
    try:
        yield
    except AbdmError as e:
        if not e.field and 400 <= e.status < 500 and e.status not in (401, 429):  # noqa: PLR2004
            e.field = name
        raise


def _account_summary(account: dict) -> dict:
    profile = abha.normalise_profile(account)
    return {
        key: profile[key]
        for key in (
            "abha_number",
            "abha_address",
            "name",
            "gender",
            "year_of_birth",
            "photo",
            "status",
            "kyc_verified",
        )
    }


def _full_abha_number(value: str) -> str:
    """ABDM can mask the numbers it lists; only a whole number identifies."""
    return value if len(abha.digits(value)) == ABHA_NUMBER_LENGTH else ""


def journey_state(txn: AbhaTransaction) -> dict:
    otp_for = OTP_STEPS.get(txn.pending_step)
    step = "otp" if otp_for else txn.pending_step
    state = {
        "transaction_id": txn.id,
        "step": step,
        "otp_for": otp_for,
        "flow": txn.flow,
        "identifier_type": txn.identifier_type,
        "otp_system": txn.otp_system,
        "masked_mobile": txn.masked_mobile,
        "message": txn.message,
        "resend": None,
        "accounts": [],
        "create_allowed": step == "not_found" and txn.aadhaar_not_found,
        "profile": txn.profile,
        "abha_number": txn.abha_number,
        "abha_address": txn.abha_address,
        "is_new": txn.is_new,
        "linked_patient": None,
    }
    if otp_for:
        state["resend"] = {
            "remaining": txn.resend_remaining(),
            "available_in": txn.resend_wait(),
        }
    if step == "choose_account":
        state["accounts"] = [
            {
                **account,
                "index": index,
                "linked_patient": patient_summary(
                    find_linked_patient(
                        abha_number=_full_abha_number(account.get("abha_number", "")),
                        abha_address=account.get("abha_address", ""),
                    )
                ),
            }
            for index, account in enumerate(txn.accounts)
        ]
    if step == "verified":
        state["linked_patient"] = patient_summary(
            find_linked_patient(
                abha_number=_full_abha_number(txn.abha_number),
                abha_address=txn.abha_address,
            )
        )
    return state


class AbhaViewSet(GenericViewSet):
    def get_exception_handler(self):
        return abdm_exception_handler

    def initial(self, request, *args, **kwargs):
        super().initial(request, *args, **kwargs)
        if self.action != "config" and not settings.ABDM_ENABLED:
            raise AbdmError(
                503,
                "ABDM is not enabled on this CARE server.",
                code="abdm_disabled",
            )

    def finalize_response(self, request, response, *args, **kwargs):
        response = super().finalize_response(request, response, *args, **kwargs)
        # Responses carry identity details and must not be cached.
        response["Cache-Control"] = "no-store"
        return response

    # Authorization

    def authorize_start(self, user, patient_id) -> Patient | None:
        """
        A journey is for an existing patient the user may update, or for
        registering a new patient.
        """
        if patient_id:
            patient = get_object_or_404(Patient, external_id=patient_id)
            if not AuthorizationController.call(
                "can_write_patient_obj", user, patient
            ):
                raise PermissionDenied("You do not have permission to update this patient.")
            return patient
        if not (
            user.is_superuser
            or AuthorizationController.call("can_create_patient", user)
        ):
            raise PermissionDenied("You do not have permission to register patients.")
        return None

    def get_facility(self, user, facility_id) -> Facility | None:
        if not facility_id:
            return None
        facility = get_object_or_404(Facility, external_id=facility_id)
        if not (
            user.is_superuser
            or FacilityOrganizationUser.objects.filter(
                user=user, organization__facility=facility
            ).exists()
        ):
            raise PermissionDenied("You are not a member of this facility.")
        return facility

    def can_link(self, user, patient: Patient, txn: AbhaTransaction) -> bool:
        if AuthorizationController.call("can_write_patient_obj", user, patient):
            return True
        # A desk registering a patient often has no write access to the record
        # it has just created. It may link the ABHA it verified for that
        # registration to the patient it created after starting the journey.
        return (
            not txn.patient_id
            and patient.created_by_id == user.id
            and patient.created_date.timestamp() >= txn.created_at
        )

    # Journey helpers

    def load(self, request, transaction_id, *steps) -> AbhaTransaction:
        txn = AbhaTransaction.load(transaction_id, request.user)
        if steps and txn.pending_step not in steps:
            raise JourneyError(
                "invalid_step",
                "This step is not available now. Please continue the ABHA "
                "journey from where it is.",
                step=journey_state(txn)["step"],
            )
        return txn

    def load_from_query(self, request, *steps) -> AbhaTransaction:
        data = TransactionRequest.model_validate(
            {"transaction_id": request.query_params.get("transaction_id")}
        )
        return self.load(request, data.transaction_id, *steps)

    def respond(self, txn: AbhaTransaction) -> Response:
        txn.save()
        return Response(journey_state(txn))

    def not_found(self, txn: AbhaTransaction, error: AbdmError) -> Response:
        txn.pending_step = "not_found"
        txn.message = error.message
        txn.otp_sent_at = None
        # Only a lookup by Aadhaar number can lead to creation: the ABHA is
        # made from that Aadhaar, which was just shown to hold none.
        txn.aadhaar_not_found = txn.identifier_type == "aadhaar"
        return self.respond(txn)

    def set_profile(self, txn: AbhaTransaction, profile: dict) -> None:
        txn.profile = profile
        txn.abha_number = profile.get("abha_number") or ""
        txn.abha_address = profile.get("abha_address") or ""

    def complete_login(self, txn: AbhaTransaction) -> Response:
        if not txn.x_token:
            raise AbdmError(502, "ABDM did not open the ABHA. Please try again.")
        if txn.login_family == "phr":
            raw = abha.phr_profile(txn.x_token)
        else:
            raw = abha.profile_account(txn.x_token)
        self.set_profile(txn, abha.normalise_profile(raw))
        txn.t_token = ""
        txn.pending_step = "verified"
        return self.respond(txn)

    def select_account(self, txn: AbhaTransaction, index: int) -> Response:
        with default_field("account"):
            result = abha.login_verify_user(
                txn.t_token, txn.abdm_txn_id, txn.account_numbers[index]
            )
        txn.x_token = result.get("token") or ""
        return self.complete_login(txn)

    def otp_sent(self, txn: AbhaTransaction, result: dict, step: str, **kwargs):
        txn.otp_sent(result, **kwargs)
        txn.pending_step = step
        txn.masked_mobile = (
            abha.masked_mobile_from_message(txn.message) or txn.masked_mobile
        )

    def resend_login_otp(self, txn: AbhaTransaction) -> dict:
        try:
            return abha.login_request_otp(
                txn.identifier_type,
                txn.otp_system,
                txn.login_id,
                txn_id=txn.abdm_txn_id,
            )
        except AbdmError as e:
            refused_transaction = e.field == "txnId" or "transaction" in (
                e.message.lower()
            )
            if e.status != 400 or not refused_transaction:  # noqa: PLR2004
                raise
        # ABDM's login does not document a resend; if it will not reuse the
        # transaction, the OTP is requested afresh.
        logger.info("ABDM refused a login OTP resend on the same transaction")
        return abha.login_request_otp(
            txn.identifier_type, txn.otp_system, txn.login_id
        )

    # Endpoints

    @action(detail=False, methods=["get"])
    def config(self, request):
        return Response(
            {
                "enabled": settings.ABDM_ENABLED,
                "abha_address_suffix": settings.ABDM_ABHA_ADDRESS_SUFFIX,
            }
        )

    @action(detail=False, methods=["post"], url_path="login/send_otp")
    def login_send_otp(self, request):
        data = LoginSendOtpRequest.model_validate(request.data)
        patient = self.authorize_start(request.user, data.patient)
        facility = self.get_facility(request.user, data.facility)
        txn = AbhaTransaction(
            user_id=request.user.id,
            facility_id=facility.id if facility else None,
            patient_id=str(patient.external_id) if patient else None,
            identifier_type=data.identifier_type,
            otp_system=data.resolved_otp_system(),
        )
        if data.identifier_type == "aadhaar":
            if not (data.consent and data.consent.agreed):
                raise JourneyError(
                    "consent_required",
                    "The person must agree to ABDM's terms before their Aadhaar "
                    "number is used.",
                    field="consent",
                )
            consent = AbhaConsent.objects.create(
                language=data.consent.language,
                facility=facility,
                patient=patient,
                created_by=request.user,
                updated_by=request.user,
            )
            txn.consent_id = str(consent.external_id)
        if data.identifier_type == "mobile":
            txn.masked_mobile = abha.mask_mobile(data.value)

        txn.login_id = encrypt(data.value)
        if data.identifier_type == "aadhaar":
            txn.aadhaar_ciphertext = txn.login_id
        try:
            with default_field("value"):
                if data.identifier_type == "abha_address":
                    txn.login_family = "phr"
                    txn.scope = abha.ADDRESS_LOGIN_SCOPES[txn.otp_system]
                    result = abha.phr_login_request_otp(txn.otp_system, txn.login_id)
                else:
                    txn.scope = abha.LOGIN_SCOPES[(txn.identifier_type, txn.otp_system)]
                    result = abha.login_request_otp(
                        txn.identifier_type, txn.otp_system, txn.login_id
                    )
        except AbdmError as e:
            if e.code not in NOT_FOUND_CODES:
                raise
            return self.not_found(txn, e)
        self.otp_sent(txn, result, "login")
        return self.respond(txn)

    @action(detail=False, methods=["post"], url_path="login/verify_otp")
    def login_verify_otp(self, request):
        data = OtpVerifyRequest.model_validate(request.data)
        txn = self.load(request, data.transaction_id, "login")
        try:
            with default_field("otp"):
                if txn.login_family == "phr":
                    result = abha.phr_login_verify(txn.scope, txn.abdm_txn_id, data.otp)
                else:
                    result = abha.login_verify(txn.scope, txn.abdm_txn_id, data.otp)
        except AbdmError as e:
            if e.code not in NOT_FOUND_CODES:
                raise
            return self.not_found(txn, e)
        txn.abdm_txn_id = result.get("txnId") or txn.abdm_txn_id
        txn.otp_sent_at = None

        if txn.login_family == "phr":
            txn.x_token = (result.get("tokens") or {}).get("token") or ""
            return self.complete_login(txn)
        if result.get("refreshToken"):
            # Only an X-token comes with a refresh token.
            txn.x_token = result.get("token") or ""
            return self.complete_login(txn)

        # A T-token: the account has to be chosen, even when there is one.
        txn.t_token = result.get("token") or ""
        accounts = [a for a in result.get("accounts") or [] if isinstance(a, dict)]
        txn.account_numbers = [str(a.get("ABHANumber") or "") for a in accounts]
        txn.accounts = [_account_summary(a) for a in accounts]
        if not accounts:
            return self.not_found(
                txn, AbdmError(404, "No ABHA was found.", code="ABDM-1114")
            )
        if len(accounts) == 1:
            return self.select_account(txn, 0)
        txn.pending_step = "choose_account"
        return self.respond(txn)

    @action(detail=False, methods=["post"], url_path="login/verify_user")
    def login_verify_user(self, request):
        data = VerifyUserRequest.model_validate(request.data)
        txn = self.load(request, data.transaction_id, "choose_account")
        if data.account >= len(txn.account_numbers):
            raise JourneyError(
                "invalid_account", "Choose one of the listed accounts.", field="account"
            )
        return self.select_account(txn, data.account)

    @action(detail=False, methods=["post"], url_path="abha_address/search")
    def abha_address_search(self, request):
        data = AddressSearchRequest.model_validate(request.data)
        self.authorize_start(request.user, data.patient)
        try:
            with default_field("abha_address"):
                result = abha.phr_search(data.abha_address)
        except AbdmError as e:
            if e.code not in NOT_FOUND_CODES:
                raise
            result = None
        if not result:
            return Response(
                {
                    "found": False,
                    "abha_address": data.abha_address,
                    "auth_methods": [],
                    "masked_mobile": "",
                    "status": "",
                }
            )
        blocked = set(result.get("blockedAuthMethods") or [])
        auth_methods = []
        for method in result.get("authMethods") or []:
            otp_system = abha.ADDRESS_AUTH_METHODS.get(method)
            if otp_system and method not in blocked and otp_system not in auth_methods:
                auth_methods.append(otp_system)
        # The name is not shown before the person has proved it is theirs.
        return Response(
            {
                "found": True,
                "abha_address": abha.full_abha_address(result.get("abhaAddress"))
                or data.abha_address,
                "auth_methods": auth_methods,
                "masked_mobile": str(result.get("mobile") or ""),
                "status": result.get("status") or "",
            }
        )

    @action(detail=False, methods=["post"], url_path="create/send_otp")
    def create_send_otp(self, request):
        data = TransactionRequest.model_validate(request.data)
        txn = self.load(request, data.transaction_id, "not_found")
        if not (txn.aadhaar_not_found and txn.aadhaar_ciphertext):
            raise JourneyError(
                "create_not_allowed",
                "An ABHA is created only after a lookup by Aadhaar number finds none.",
            )
        result = abha.enrol_request_otp("aadhaar", txn.aadhaar_ciphertext)
        txn.flow = "create"
        txn.scope = abha.ENROL_SCOPE
        txn.otp_system = abha.OTP_SYSTEM_AADHAAR
        txn.masked_mobile = ""
        self.otp_sent(txn, result, "enrol")
        return self.respond(txn)

    @action(detail=False, methods=["post"], url_path="create/verify_otp")
    def create_verify_otp(self, request):
        data = EnrolVerifyRequest.model_validate(request.data)
        txn = self.load(request, data.transaction_id, "enrol")
        with default_field("otp"):
            result = abha.enrol_by_aadhaar(txn.abdm_txn_id, data.otp, data.mobile)
        txn.abdm_txn_id = result.get("txnId") or txn.abdm_txn_id
        txn.otp_sent_at = None
        tokens = result.get("tokens") or result.get("jwtResponse") or {}
        txn.x_token = tokens.get("token") or ""
        txn.is_new = bool(result.get("isNew"))
        if not txn.is_new:
            # The Aadhaar already held an ABHA, and this OTP has opened it.
            return self.complete_login(txn)

        raw_profile = result.get("ABHAProfile") or {}
        profile = abha.normalise_profile(raw_profile)
        txn.masked_mobile = abha.mask_mobile(data.mobile)
        if abha.mobile_verification_required(raw_profile.get("mobile"), data.mobile):
            txn.mobile_ciphertext = encrypt(data.mobile)
            txn.pending_step = "mobile_verify"
        else:
            profile["mobile"] = data.mobile
            profile["masked_mobile"] = txn.masked_mobile
            txn.pending_step = "address"
        self.set_profile(txn, profile)
        return self.respond(txn)

    @action(detail=False, methods=["post"], url_path="create/send_mobile_otp")
    def create_send_mobile_otp(self, request):
        data = TransactionRequest.model_validate(request.data)
        txn = self.load(request, data.transaction_id, "mobile_verify")
        with default_field("mobile"):
            result = abha.enrol_request_mobile_otp(
                txn.abdm_txn_id, txn.mobile_ciphertext
            )
        self.otp_sent(txn, result, "mobile_otp")
        return self.respond(txn)

    @action(detail=False, methods=["post"], url_path="create/verify_mobile_otp")
    def create_verify_mobile_otp(self, request):
        data = OtpVerifyRequest.model_validate(request.data)
        txn = self.load(request, data.transaction_id, "mobile_otp")
        with default_field("otp"):
            result = abha.enrol_verify_mobile(txn.abdm_txn_id, data.otp)
        txn.abdm_txn_id = result.get("txnId") or txn.abdm_txn_id
        txn.otp_sent_at = None
        txn.profile = {**(txn.profile or {}), "masked_mobile": txn.masked_mobile}
        txn.pending_step = "address"
        return self.respond(txn)

    @action(detail=False, methods=["get"], url_path="create/address_suggestions")
    def create_address_suggestions(self, request):
        txn = self.load_from_query(request, "address")
        result = abha.enrol_suggestions(txn.abdm_txn_id)
        txn.abdm_txn_id = result.get("txnId") or txn.abdm_txn_id
        txn.save()
        suggestions = [
            str(item).strip().lower()
            for item in result.get("abhaAddressList") or []
            if isinstance(item, str) and item.strip()
        ]
        return Response(
            {
                "suggestions": suggestions,
                "suffix": settings.ABDM_ABHA_ADDRESS_SUFFIX,
            }
        )

    @action(detail=False, methods=["post"], url_path="create/address")
    def create_address(self, request):
        data = AddressCreateRequest.model_validate(request.data)
        txn = self.load(request, data.transaction_id, "address")
        with default_field("abha_address"):
            result = abha.enrol_create_address(txn.abdm_txn_id, data.abha_address)
        txn.abdm_txn_id = result.get("txnId") or txn.abdm_txn_id
        address = abha.full_abha_address(
            result.get("preferredAbhaAddress") or data.abha_address
        )
        profile = dict(txn.profile or {})
        if txn.x_token:
            # The account as ABDM now holds it, with the new address.
            try:
                refreshed = abha.normalise_profile(abha.profile_account(txn.x_token))
            except AbdmError as e:
                logger.warning(
                    "ABDM profile after address creation request_id=%s failed: %s",
                    e.request_id,
                    e.status,
                )
            else:
                profile.update({key: value for key, value in refreshed.items() if value})
        profile["abha_address"] = address
        if result.get("healthIdNumber"):
            profile["abha_number"] = abha.format_abha_number(
                result.get("healthIdNumber")
            )
        self.set_profile(txn, profile)
        txn.pending_step = "verified"
        return self.respond(txn)

    @action(detail=False, methods=["post"], url_path="resend_otp")
    def resend_otp(self, request):
        data = TransactionRequest.model_validate(request.data)
        txn = self.load(request, data.transaction_id, *OTP_STEPS)
        if not txn.resend_remaining():
            raise JourneyError(
                "resend_limit",
                "The OTP has been resent twice already. Please start again if it "
                "has not arrived.",
            )
        wait = txn.resend_wait()
        if wait:
            raise JourneyError(
                "resend_wait",
                f"Please wait {wait} seconds before asking for the OTP again.",
                available_in=wait,
            )
        step = txn.pending_step
        if step == "enrol":
            result = abha.enrol_request_otp(
                "aadhaar", txn.aadhaar_ciphertext, txn_id=txn.abdm_txn_id
            )
        elif step == "mobile_otp":
            result = abha.enrol_request_mobile_otp(
                txn.abdm_txn_id, txn.mobile_ciphertext
            )
        elif txn.login_family == "phr":
            # ABDM's ABHA address login takes no transaction to resend on.
            result = abha.phr_login_request_otp(txn.otp_system, txn.login_id)
        else:
            result = self.resend_login_otp(txn)
        self.otp_sent(txn, result, step, resend=True)
        return self.respond(txn)

    @action(detail=False, methods=["get"])
    def state(self, request):
        return Response(journey_state(self.load_from_query(request)))

    @action(detail=False, methods=["get"])
    def card(self, request):
        txn = self.load_from_query(request, "verified")
        if not txn.x_token:
            raise JourneyError(
                "card_unavailable", "The ABHA card is not available for this session."
            )
        if txn.login_family == "phr":
            response = abha.phr_card(txn.x_token)
        else:
            response = abha.profile_card(txn.x_token)
        content_type = response.content_type.split(";")[0].strip().lower()
        if content_type == "application/octet-stream":
            content_type = "image/png"
        if not response.content or not content_type.startswith("image/"):
            raise AbdmError(
                502,
                "ABDM did not return the ABHA card. Please try again.",
                request_id=response.request_id,
            )
        card = HttpResponse(response.content, content_type=content_type)
        card["Content-Disposition"] = 'inline; filename="abha-card.png"'
        return card

    @action(detail=False, methods=["post"])
    def link(self, request):
        data = LinkRequest.model_validate(request.data)
        txn = self.load(request, data.transaction_id, "verified")
        patient = get_object_or_404(Patient, external_id=data.patient)
        if txn.patient_id and txn.patient_id != str(patient.external_id):
            raise JourneyError(
                "patient_mismatch", "This ABHA was verified for a different patient."
            )
        if not self.can_link(request.user, patient, txn):
            raise PermissionDenied("You do not have permission to update this patient.")
        abha_number = _full_abha_number(txn.abha_number)
        if not (abha_number or txn.abha_address):
            raise JourneyError(
                "abha_missing", "ABDM did not return an ABHA number or address to link."
            )
        link_abha_to_patient(patient, abha_number, txn.abha_address)
        if txn.consent_id:
            AbhaConsent.objects.filter(external_id=txn.consent_id).update(
                patient=patient, abha_number=abha_number
            )
        txn.patient_id = str(patient.external_id)
        txn.save()
        return Response(
            {
                "patient": patient_summary(patient),
                "abha_number": abha_number,
                "abha_address": txn.abha_address,
            }
        )

"""
ABHA at the registration desk: find a person's ABHA by Aadhaar number, mobile
number, ABHA number or ABHA address, create one by Aadhaar OTP when a lookup
by Aadhaar finds none, and link the verified ABHA to a CARE patient.

A journey is an `AbhaTransaction` kept on the server. The browser holds its
id and is told the step it is on and what the screen should show; ABDM's
transaction ids and tokens stay here.
"""

import logging
from contextlib import contextmanager

from django.conf import settings
from django.http import HttpResponse
from pydantic import ValidationError
from rest_framework.decorators import action
from rest_framework.exceptions import PermissionDenied
from rest_framework.response import Response
from rest_framework.viewsets import GenericViewSet

from care.abdm import abha
from care.abdm.api.specs import (
    AddressCreateRequest,
    AddressSearchRequest,
    EnrolVerifyRequest,
    LinkRequest,
    LoginSendOtpRequest,
    OtpVerifyRequest,
    TransactionRequest,
    VerifyUserRequest,
)
from care.abdm.client import GATEWAY_TOKEN_ERROR_CODES, AbdmError, encrypt
from care.abdm.identifiers import (
    AbhaLinkError,
    find_linked_patient,
    link_abha_to_patient,
)
from care.abdm.models import AbhaConsent
from care.abdm.transaction import AbhaTransaction
from care.emr.api.viewsets.base import emr_exception_handler
from care.emr.models.organization import FacilityOrganizationUser
from care.emr.models.patient import Patient
from care.facility.models.facility import Facility
from care.security.authorization import AuthorizationController
from care.utils.shortcuts import get_object_or_404

logger = logging.getLogger(__name__)

# The only answers that mean nobody holds an ABHA for what was entered:
# ABDM-1114 for the Aadhaar, mobile and ABHA number lookups, ABDM-1211 for an
# ABHA address. Any other refusal is shown as it is, never as "not found".
NOT_FOUND_CODES = {"ABDM-1114", "ABDM-1211"}

# Steps waiting for an OTP, and whose OTP it is.
OTP_STEPS = {"login": "login", "enrol": "enrol", "mobile_otp": "mobile"}

# ABDM's names for request fields, as the desk's form names them.
FIELD_NAMES = {
    "otpValue": "otp",
    "otp": "otp",
    "loginId": "value",
    "value": "value",
    "mobile": "mobile",
    "abhaAddress": "abha_address",
    "abha_address": "abha_address",
    "ABHANumber": "account",
    "account": "account",
}

GATEWAY_AUTH_MESSAGE = "Could not authenticate with ABDM. Please try again."
ABHA_NUMBER_LENGTH = 14


class JourneyError(Exception):
    """A request the journey refuses on its own, before or instead of ABDM."""

    def __init__(self, error_type, message, *, field=None, status=400, **extra):
        super().__init__(message)
        self.error_type = error_type
        self.message = message
        self.field = field
        self.status = status
        self.extra = extra


def _abdm_status(exc: AbdmError) -> int:
    if exc.status == 429:  # noqa: PLR2004
        return 429
    if exc.status == 401 and exc.code in GATEWAY_TOKEN_ERROR_CODES:  # noqa: PLR2004
        return 502
    if 400 <= exc.status < 500:  # noqa: PLR2004
        return 400
    if exc.status == 502:  # noqa: PLR2004
        return 502
    return 503


def _error(error_type, message, field=None, **extra) -> dict:
    error = {"type": error_type, "msg": message, **extra}
    if field:
        error["loc"] = [field]
    return error


def patient_summary(patient: Patient | None) -> dict | None:
    if not patient:
        return None
    return {"id": str(patient.external_id), "name": patient.name}


def abdm_exception_handler(exc, context):
    if isinstance(exc, AbdmError):
        status = _abdm_status(exc)
        gateway_auth = exc.status == 401 and exc.code in GATEWAY_TOKEN_ERROR_CODES  # noqa: PLR2004
        message = GATEWAY_AUTH_MESSAGE if gateway_auth else exc.message
        field = FIELD_NAMES.get(exc.field) if status == 400 else None  # noqa: PLR2004
        error = _error(
            "abdm_error", message, field, code=exc.code, request_id=exc.request_id
        )
        return Response({"errors": [error]}, status=status)
    if isinstance(exc, JourneyError):
        error = _error(exc.error_type, exc.message, exc.field, **exc.extra)
        return Response({"errors": [error]}, status=exc.status)
    if isinstance(exc, AbhaLinkError):
        error = _error(
            exc.error_type, exc.message, patient=patient_summary(exc.patient)
        )
        return Response({"errors": [error]}, status=400)
    if isinstance(exc, ValidationError):
        # The submitted values are not echoed back: they are Aadhaar numbers,
        # mobiles and OTPs.
        errors = [
            _error(
                "validation_error",
                error["msg"].removeprefix("Value error, "),
                ".".join(str(part) for part in error["loc"]) or None,
            )
            for error in exc.errors(include_url=False, include_input=False)
        ]
        return Response({"errors": errors}, status=400)
    return emr_exception_handler(exc, context)


@contextmanager
def default_field(name: str):
    """Attribute a refusal that names no field to the field just submitted."""
    try:
        yield
    except AbdmError as e:
        if not e.field and 400 <= e.status < 500 and e.status not in (401, 429):  # noqa: PLR2004
            e.field = name
        raise


def _account_summary(account: dict) -> dict:
    profile = abha.normalise_profile(account)
    return {
        key: profile[key]
        for key in (
            "abha_number",
            "abha_address",
            "name",
            "gender",
            "year_of_birth",
            "photo",
            "status",
            "kyc_verified",
        )
    }


def _full_abha_number(value: str) -> str:
    """ABDM can mask the numbers it lists; only a whole number identifies."""
    return value if len(abha.digits(value)) == ABHA_NUMBER_LENGTH else ""


def journey_state(txn: AbhaTransaction) -> dict:
    otp_for = OTP_STEPS.get(txn.pending_step)
    step = "otp" if otp_for else txn.pending_step
    state = {
        "transaction_id": txn.id,
        "step": step,
        "otp_for": otp_for,
        "flow": txn.flow,
        "identifier_type": txn.identifier_type,
        "otp_system": txn.otp_system,
        "masked_mobile": txn.masked_mobile,
        "message": txn.message,
        "resend": None,
        "accounts": [],
        "create_allowed": step == "not_found" and txn.aadhaar_not_found,
        "profile": txn.profile,
        "abha_number": txn.abha_number,
        "abha_address": txn.abha_address,
        "is_new": txn.is_new,
        "linked_patient": None,
    }
    if otp_for:
        state["resend"] = {
            "remaining": txn.resend_remaining(),
            "available_in": txn.resend_wait(),
        }
    if step == "choose_account":
        state["accounts"] = [
            {
                **account,
                "index": index,
                "linked_patient": patient_summary(
                    find_linked_patient(
                        abha_number=_full_abha_number(account.get("abha_number", "")),
                        abha_address=account.get("abha_address", ""),
                    )
                ),
            }
            for index, account in enumerate(txn.accounts)
        ]
    if step == "verified":
        state["linked_patient"] = patient_summary(
            find_linked_patient(
                abha_number=_full_abha_number(txn.abha_number),
                abha_address=txn.abha_address,
            )
        )
    return state


class AbhaViewSet(GenericViewSet):
    def get_exception_handler(self):
        return abdm_exception_handler

    def initial(self, request, *args, **kwargs):
        super().initial(request, *args, **kwargs)
        if self.action != "config" and not settings.ABDM_ENABLED:
            raise AbdmError(
                503,
                "ABDM is not enabled on this CARE server.",
                code="abdm_disabled",
            )

    def finalize_response(self, request, response, *args, **kwargs):
        response = super().finalize_response(request, response, *args, **kwargs)
        # Responses carry identity details and must not be cached.
        response["Cache-Control"] = "no-store"
        return response

    # Authorization

    def authorize_start(self, user, patient_id) -> Patient | None:
        """
        A journey is for an existing patient the user may update, or for
        registering a new patient.
        """
        if patient_id:
            patient = get_object_or_404(Patient, external_id=patient_id)
            if not AuthorizationController.call(
                "can_write_patient_obj", user, patient
            ):
                raise PermissionDenied("You do not have permission to update this patient.")
            return patient
        if not (
            user.is_superuser
            or AuthorizationController.call("can_create_patient", user)
        ):
            raise PermissionDenied("You do not have permission to register patients.")
        return None

    def get_facility(self, user, facility_id) -> Facility | None:
        if not facility_id:
            return None
        facility = get_object_or_404(Facility, external_id=facility_id)
        if not (
            user.is_superuser
            or FacilityOrganizationUser.objects.filter(
                user=user, organization__facility=facility
            ).exists()
        ):
            raise PermissionDenied("You are not a member of this facility.")
        return facility

    def can_link(self, user, patient: Patient, txn: AbhaTransaction) -> bool:
        if AuthorizationController.call("can_write_patient_obj", user, patient):
            return True
        # A desk registering a patient often has no write access to the record
        # it has just created. It may link the ABHA it verified for that
        # registration to the patient it created after starting the journey.
        return (
            not txn.patient_id
            and patient.created_by_id == user.id
            and patient.created_date.timestamp() >= txn.created_at
        )

    # Journey helpers

    def load(self, request, transaction_id, *steps) -> AbhaTransaction:
        txn = AbhaTransaction.load(transaction_id, request.user)
        if steps and txn.pending_step not in steps:
            raise JourneyError(
                "invalid_step",
                "This step is not available now. Please continue the ABHA "
                "journey from where it is.",
                step=journey_state(txn)["step"],
            )
        return txn

    def load_from_query(self, request, *steps) -> AbhaTransaction:
        data = TransactionRequest.model_validate(
            {"transaction_id": request.query_params.get("transaction_id")}
        )
        return self.load(request, data.transaction_id, *steps)

    def respond(self, txn: AbhaTransaction) -> Response:
        txn.save()
        return Response(journey_state(txn))

    def not_found(self, txn: AbhaTransaction, error: AbdmError) -> Response:
        txn.pending_step = "not_found"
        txn.message = error.message
        txn.otp_sent_at = None
        # Only a lookup by Aadhaar number can lead to creation: the ABHA is
        # made from that Aadhaar, which was just shown to hold none.
        txn.aadhaar_not_found = txn.identifier_type == "aadhaar"
        return self.respond(txn)

    def set_profile(self, txn: AbhaTransaction, profile: dict) -> None:
        txn.profile = profile
        txn.abha_number = profile.get("abha_number") or ""
        txn.abha_address = profile.get("abha_address") or ""

    def complete_login(self, txn: AbhaTransaction) -> Response:
        if not txn.x_token:
            raise AbdmError(502, "ABDM did not open the ABHA. Please try again.")
        if txn.login_family == "phr":
            raw = abha.phr_profile(txn.x_token)
        else:
            raw = abha.profile_account(txn.x_token)
        self.set_profile(txn, abha.normalise_profile(raw))
        txn.t_token = ""
        txn.pending_step = "verified"
        return self.respond(txn)

    def select_account(self, txn: AbhaTransaction, index: int) -> Response:
        with default_field("account"):
            result = abha.login_verify_user(
                txn.t_token, txn.abdm_txn_id, txn.account_numbers[index]
            )
        txn.x_token = result.get("token") or ""
        return self.complete_login(txn)

    def otp_sent(self, txn: AbhaTransaction, result: dict, step: str, **kwargs):
        txn.otp_sent(result, **kwargs)
        txn.pending_step = step
        txn.masked_mobile = (
            abha.masked_mobile_from_message(txn.message) or txn.masked_mobile
        )

    def resend_login_otp(self, txn: AbhaTransaction) -> dict:
        try:
            return abha.login_request_otp(
                txn.identifier_type,
                txn.otp_system,
                txn.login_id,
                txn_id=txn.abdm_txn_id,
            )
        except AbdmError as e:
            refused_transaction = e.field == "txnId" or "transaction" in (
                e.message.lower()
            )
            if e.status != 400 or not refused_transaction:  # noqa: PLR2004
                raise
        # ABDM's login does not document a resend; if it will not reuse the
        # transaction, the OTP is requested afresh.
        logger.info("ABDM refused a login OTP resend on the same transaction")
        return abha.login_request_otp(
            txn.identifier_type, txn.otp_system, txn.login_id
        )

    # Endpoints

    @action(detail=False, methods=["get"])
    def config(self, request):
        return Response(
            {
                "enabled": settings.ABDM_ENABLED,
                "abha_address_suffix": settings.ABDM_ABHA_ADDRESS_SUFFIX,
            }
        )

    @action(detail=False, methods=["post"], url_path="login/send_otp")
    def login_send_otp(self, request):
        data = LoginSendOtpRequest.model_validate(request.data)
        patient = self.authorize_start(request.user, data.patient)
        facility = self.get_facility(request.user, data.facility)
        txn = AbhaTransaction(
            user_id=request.user.id,
            facility_id=facility.id if facility else None,
            patient_id=str(patient.external_id) if patient else None,
            identifier_type=data.identifier_type,
            otp_system=data.resolved_otp_system(),
        )
        if data.identifier_type == "aadhaar":
            if not (data.consent and data.consent.agreed):
                raise JourneyError(
                    "consent_required",
                    "The person must agree to ABDM's terms before their Aadhaar "
                    "number is used.",
                    field="consent",
                )
            consent = AbhaConsent.objects.create(
                language=data.consent.language,
                facility=facility,
                patient=patient,
                created_by=request.user,
                updated_by=request.user,
            )
            txn.consent_id = str(consent.external_id)
        if data.identifier_type == "mobile":
            txn.masked_mobile = abha.mask_mobile(data.value)

        txn.login_id = encrypt(data.value)
        if data.identifier_type == "aadhaar":
            txn.aadhaar_ciphertext = txn.login_id
        try:
            with default_field("value"):
                if data.identifier_type == "abha_address":
                    txn.login_family = "phr"
                    txn.scope = abha.ADDRESS_LOGIN_SCOPES[txn.otp_system]
                    result = abha.phr_login_request_otp(txn.otp_system, txn.login_id)
                else:
                    txn.scope = abha.LOGIN_SCOPES[(txn.identifier_type, txn.otp_system)]
                    result = abha.login_request_otp(
                        txn.identifier_type, txn.otp_system, txn.login_id
                    )
        except AbdmError as e:
            if e.code not in NOT_FOUND_CODES:
                raise
            return self.not_found(txn, e)
        self.otp_sent(txn, result, "login")
        return self.respond(txn)

    @action(detail=False, methods=["post"], url_path="login/verify_otp")
    def login_verify_otp(self, request):
        data = OtpVerifyRequest.model_validate(request.data)
        txn = self.load(request, data.transaction_id, "login")
        try:
            with default_field("otp"):
                if txn.login_family == "phr":
                    result = abha.phr_login_verify(txn.scope, txn.abdm_txn_id, data.otp)
                else:
                    result = abha.login_verify(txn.scope, txn.abdm_txn_id, data.otp)
        except AbdmError as e:
            if e.code not in NOT_FOUND_CODES:
                raise
            return self.not_found(txn, e)
        txn.abdm_txn_id = result.get("txnId") or txn.abdm_txn_id
        txn.otp_sent_at = None

        if txn.login_family == "phr":
            txn.x_token = (result.get("tokens") or {}).get("token") or ""
            return self.complete_login(txn)
        if result.get("refreshToken"):
            # Only an X-token comes with a refresh token.
            txn.x_token = result.get("token") or ""
            return self.complete_login(txn)

        # A T-token: the account has to be chosen, even when there is one.
        txn.t_token = result.get("token") or ""
        accounts = [a for a in result.get("accounts") or [] if isinstance(a, dict)]
        txn.account_numbers = [str(a.get("ABHANumber") or "") for a in accounts]
        txn.accounts = [_account_summary(a) for a in accounts]
        if not accounts:
            return self.not_found(
                txn, AbdmError(404, "No ABHA was found.", code="ABDM-1114")
            )
        if len(accounts) == 1:
            return self.select_account(txn, 0)
        txn.pending_step = "choose_account"
        return self.respond(txn)

    @action(detail=False, methods=["post"], url_path="login/verify_user")
    def login_verify_user(self, request):
        data = VerifyUserRequest.model_validate(request.data)
        txn = self.load(request, data.transaction_id, "choose_account")
        if data.account >= len(txn.account_numbers):
            raise JourneyError(
                "invalid_account", "Choose one of the listed accounts.", field="account"
            )
        return self.select_account(txn, data.account)

    @action(detail=False, methods=["post"], url_path="abha_address/search")
    def abha_address_search(self, request):
        data = AddressSearchRequest.model_validate(request.data)
        self.authorize_start(request.user, data.patient)
        try:
            with default_field("abha_address"):
                result = abha.phr_search(data.abha_address)
        except AbdmError as e:
            if e.code not in NOT_FOUND_CODES:
                raise
            result = None
        if not result:
            return Response(
                {
                    "found": False,
                    "abha_address": data.abha_address,
                    "auth_methods": [],
                    "masked_mobile": "",
                    "status": "",
                }
            )
        blocked = set(result.get("blockedAuthMethods") or [])
        auth_methods = []
        for method in result.get("authMethods") or []:
            otp_system = abha.ADDRESS_AUTH_METHODS.get(method)
            if otp_system and method not in blocked and otp_system not in auth_methods:
                auth_methods.append(otp_system)
        # The name is not shown before the person has proved it is theirs.
        return Response(
            {
                "found": True,
                "abha_address": abha.full_abha_address(result.get("abhaAddress"))
                or data.abha_address,
                "auth_methods": auth_methods,
                "masked_mobile": str(result.get("mobile") or ""),
                "status": result.get("status") or "",
            }
        )

    @action(detail=False, methods=["post"], url_path="create/send_otp")
    def create_send_otp(self, request):
        data = TransactionRequest.model_validate(request.data)
        txn = self.load(request, data.transaction_id, "not_found")
        if not (txn.aadhaar_not_found and txn.aadhaar_ciphertext):
            raise JourneyError(
                "create_not_allowed",
                "An ABHA is created only after a lookup by Aadhaar number finds none.",
            )
        result = abha.enrol_request_otp("aadhaar", txn.aadhaar_ciphertext)
        txn.flow = "create"
        txn.scope = abha.ENROL_SCOPE
        txn.otp_system = abha.OTP_SYSTEM_AADHAAR
        txn.masked_mobile = ""
        self.otp_sent(txn, result, "enrol")
        return self.respond(txn)

    @action(detail=False, methods=["post"], url_path="create/verify_otp")
    def create_verify_otp(self, request):
        data = EnrolVerifyRequest.model_validate(request.data)
        txn = self.load(request, data.transaction_id, "enrol")
        with default_field("otp"):
            result = abha.enrol_by_aadhaar(txn.abdm_txn_id, data.otp, data.mobile)
        txn.abdm_txn_id = result.get("txnId") or txn.abdm_txn_id
        txn.otp_sent_at = None
        tokens = result.get("tokens") or result.get("jwtResponse") or {}
        txn.x_token = tokens.get("token") or ""
        txn.is_new = bool(result.get("isNew"))
        if not txn.is_new:
            # The Aadhaar already held an ABHA, and this OTP has opened it.
            return self.complete_login(txn)

        raw_profile = result.get("ABHAProfile") or {}
        profile = abha.normalise_profile(raw_profile)
        txn.masked_mobile = abha.mask_mobile(data.mobile)
        if abha.mobile_verification_required(raw_profile.get("mobile"), data.mobile):
            txn.mobile_ciphertext = encrypt(data.mobile)
            txn.pending_step = "mobile_verify"
        else:
            profile["mobile"] = data.mobile
            profile["masked_mobile"] = txn.masked_mobile
            txn.pending_step = "address"
        self.set_profile(txn, profile)
        return self.respond(txn)

    @action(detail=False, methods=["post"], url_path="create/send_mobile_otp")
    def create_send_mobile_otp(self, request):
        data = TransactionRequest.model_validate(request.data)
        txn = self.load(request, data.transaction_id, "mobile_verify")
        with default_field("mobile"):
            result = abha.enrol_request_mobile_otp(
                txn.abdm_txn_id, txn.mobile_ciphertext
            )
        self.otp_sent(txn, result, "mobile_otp")
        return self.respond(txn)

    @action(detail=False, methods=["post"], url_path="create/verify_mobile_otp")
    def create_verify_mobile_otp(self, request):
        data = OtpVerifyRequest.model_validate(request.data)
        txn = self.load(request, data.transaction_id, "mobile_otp")
        with default_field("otp"):
            result = abha.enrol_verify_mobile(txn.abdm_txn_id, data.otp)
        txn.abdm_txn_id = result.get("txnId") or txn.abdm_txn_id
        txn.otp_sent_at = None
        txn.profile = {**(txn.profile or {}), "masked_mobile": txn.masked_mobile}
        txn.pending_step = "address"
        return self.respond(txn)

    @action(detail=False, methods=["get"], url_path="create/address_suggestions")
    def create_address_suggestions(self, request):
        txn = self.load_from_query(request, "address")
        result = abha.enrol_suggestions(txn.abdm_txn_id)
        txn.abdm_txn_id = result.get("txnId") or txn.abdm_txn_id
        txn.save()
        suggestions = [
            str(item).strip().lower()
            for item in result.get("abhaAddressList") or []
            if isinstance(item, str) and item.strip()
        ]
        return Response(
            {
                "suggestions": suggestions,
                "suffix": settings.ABDM_ABHA_ADDRESS_SUFFIX,
            }
        )

    @action(detail=False, methods=["post"], url_path="create/address")
    def create_address(self, request):
        data = AddressCreateRequest.model_validate(request.data)
        txn = self.load(request, data.transaction_id, "address")
        with default_field("abha_address"):
            result = abha.enrol_create_address(txn.abdm_txn_id, data.abha_address)
        txn.abdm_txn_id = result.get("txnId") or txn.abdm_txn_id
        address = abha.full_abha_address(
            result.get("preferredAbhaAddress") or data.abha_address
        )
        profile = dict(txn.profile or {})
        if txn.x_token:
            # The account as ABDM now holds it, with the new address.
            try:
                refreshed = abha.normalise_profile(abha.profile_account(txn.x_token))
            except AbdmError as e:
                logger.warning(
                    "ABDM profile after address creation request_id=%s failed: %s",
                    e.request_id,
                    e.status,
                )
            else:
                profile.update({key: value for key, value in refreshed.items() if value})
        profile["abha_address"] = address
        if result.get("healthIdNumber"):
            profile["abha_number"] = abha.format_abha_number(
                result.get("healthIdNumber")
            )
        self.set_profile(txn, profile)
        txn.pending_step = "verified"
        return self.respond(txn)

    @action(detail=False, methods=["post"], url_path="resend_otp")
    def resend_otp(self, request):
        data = TransactionRequest.model_validate(request.data)
        txn = self.load(request, data.transaction_id, *OTP_STEPS)
        if not txn.resend_remaining():
            raise JourneyError(
                "resend_limit",
                "The OTP has been resent twice already. Please start again if it "
                "has not arrived.",
            )
        wait = txn.resend_wait()
        if wait:
            raise JourneyError(
                "resend_wait",
                f"Please wait {wait} seconds before asking for the OTP again.",
                available_in=wait,
            )
        step = txn.pending_step
        if step == "enrol":
            result = abha.enrol_request_otp(
                "aadhaar", txn.aadhaar_ciphertext, txn_id=txn.abdm_txn_id
            )
        elif step == "mobile_otp":
            result = abha.enrol_request_mobile_otp(
                txn.abdm_txn_id, txn.mobile_ciphertext
            )
        elif txn.login_family == "phr":
            # ABDM's ABHA address login takes no transaction to resend on.
            result = abha.phr_login_request_otp(txn.otp_system, txn.login_id)
        else:
            result = self.resend_login_otp(txn)
        self.otp_sent(txn, result, step, resend=True)
        return self.respond(txn)

    @action(detail=False, methods=["get"])
    def state(self, request):
        return Response(journey_state(self.load_from_query(request)))

    @action(detail=False, methods=["get"])
    def card(self, request):
        txn = self.load_from_query(request, "verified")
        if not txn.x_token:
            raise JourneyError(
                "card_unavailable", "The ABHA card is not available for this session."
            )
        if txn.login_family == "phr":
            response = abha.phr_card(txn.x_token)
        else:
            response = abha.profile_card(txn.x_token)
        content_type = response.content_type.split(";")[0].strip().lower()
        if content_type == "application/octet-stream":
            content_type = "image/png"
        if not response.content or not content_type.startswith("image/"):
            raise AbdmError(
                502,
                "ABDM did not return the ABHA card. Please try again.",
                request_id=response.request_id,
            )
        card = HttpResponse(response.content, content_type=content_type)
        card["Content-Disposition"] = 'inline; filename="abha-card.png"'
        return card

    @action(detail=False, methods=["post"])
    def link(self, request):
        data = LinkRequest.model_validate(request.data)
        txn = self.load(request, data.transaction_id, "verified")
        patient = get_object_or_404(Patient, external_id=data.patient)
        if txn.patient_id and txn.patient_id != str(patient.external_id):
            raise JourneyError(
                "patient_mismatch", "This ABHA was verified for a different patient."
            )
        if not self.can_link(request.user, patient, txn):
            raise PermissionDenied("You do not have permission to update this patient.")
        abha_number = _full_abha_number(txn.abha_number)
        if not (abha_number or txn.abha_address):
            raise JourneyError(
                "abha_missing", "ABDM did not return an ABHA number or address to link."
            )
        link_abha_to_patient(patient, abha_number, txn.abha_address)
        if txn.consent_id:
            AbhaConsent.objects.filter(external_id=txn.consent_id).update(
                patient=patient, abha_number=abha_number
            )
        txn.patient_id = str(patient.external_id)
        txn.save()
        return Response(
            {
                "patient": patient_summary(patient),
                "abha_number": abha_number,
                "abha_address": txn.abha_address,
            }
        )

