import base64
import json
from unittest import mock

import requests
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import padding, rsa
from django.core.cache import cache
from django.test import SimpleTestCase, override_settings

from care.abdm import client
from care.abdm.client import AbdmError

ABDM_SETTINGS = {
    "ABDM_CLIENT_ID": "client-id",
    "ABDM_CLIENT_SECRET": "client-secret",
    "ABDM_GATEWAY_URL": "https://gateway.test",
    "ABDM_ABHA_URL": "https://abha.test/abha/api",
    "ABDM_CM_ID": "sbx",
    "ABDM_ABHA_ADDRESS_SUFFIX": "sbx",
    "ABDM_REQUEST_TIMEOUT": 5,
}

OAEP = "RSA/ECB/OAEPWithSHA-1AndMGF1Padding"
PKCS1 = "RSA/ECB/PKCS1Padding"


def fake_response(status_code=200, data=None, content_type="application/json"):
    response = mock.Mock()
    response.status_code = status_code
    response.headers = {"Content-Type": content_type}
    response.content = json.dumps(data).encode() if data is not None else b""
    response.json = lambda: json.loads(response.content)
    return response


def public_key_base64(private_key) -> str:
    der = private_key.public_key().public_bytes(
        serialization.Encoding.DER,
        serialization.PublicFormat.SubjectPublicKeyInfo,
    )
    return base64.b64encode(der).decode()


class AbdmCacheMixin:
    def setUp(self):
        super().setUp()
        cache.delete_many(
            [client.SESSION_TOKEN_CACHE_KEY, client.PUBLIC_CERTIFICATE_CACHE_KEY]
        )
        self.addCleanup(
            cache.delete_many,
            [client.SESSION_TOKEN_CACHE_KEY, client.PUBLIC_CERTIFICATE_CACHE_KEY],
        )


class NormaliseErrorTests(SimpleTestCase):
    def test_error_shapes(self):
        cases = [
            (
                {"error": {"code": "ABDM-1114", "message": "No account found"}},
                ("ABDM-1114", "No account found", ""),
            ),
            (
                [{"code": "ABDM-1006: ", "message": "Invalid Aadhaar"}],
                ("ABDM-1006", "Invalid Aadhaar", ""),
            ),
            (
                {"code": "900901", "message": "Invalid Credentials", "description": "x"},
                ("900901", "Invalid Credentials", ""),
            ),
            (
                {"code": "ABDM-9999", "description": "Only a description"},
                ("ABDM-9999", "Only a description", ""),
            ),
            (
                {"error": "Bad Request", "path": "/v3/x", "status": 400},
                ("", "Bad Request", ""),
            ),
            (
                {"otpValue": "Invalid OTP value", "timestamp": "2024-01-01"},
                ("", "Invalid OTP value", "otpValue"),
            ),
            (
                {"txnId": "Invalid Transaction Id", "timestamp": "2024-01-01"},
                ("", "Invalid Transaction Id", "txnId"),
            ),
            (
                {"txnId": "0f2a-77b1", "loginId": "Invalid LoginId"},
                ("", "Invalid LoginId", "loginId"),
            ),
        ]
        for data, expected in cases:
            with self.subTest(data=data):
                self.assertEqual(client.normalise_error(400, data), expected)

    def test_default_messages(self):
        self.assertEqual(
            client.normalise_error(429, None),
            ("", client.DEFAULT_ERROR_MESSAGES[429], ""),
        )
        self.assertEqual(
            client.normalise_error(500, None), ("", client.UNAVAILABLE_MESSAGE, "")
        )
        # An echoed transaction id alone is not an error message.
        self.assertEqual(
            client.normalise_error(400, {"txnId": "0f2a-77b1"}),
            ("", client.DEFAULT_ERROR_MESSAGES[400], ""),
        )


@override_settings(**ABDM_SETTINGS)
@mock.patch("care.abdm.client.requests.request")
class RequestTests(AbdmCacheMixin, SimpleTestCase):
    def test_session_token_is_requested_once_and_cached(self, http):
        http.return_value = fake_response(
            data={"accessToken": "session-token", "expiresIn": 1200}
        )
        self.assertEqual(client.get_session_token(), "session-token")
        self.assertEqual(client.get_session_token(), "session-token")

        http.assert_called_once()
        method, url = http.call_args.args
        self.assertEqual(method, "POST")
        self.assertEqual(url, "https://gateway.test/api/hiecm/gateway/v3/sessions")
        headers = http.call_args.kwargs["headers"]
        self.assertEqual(headers["X-CM-ID"], "sbx")
        self.assertTrue(headers["REQUEST-ID"])
        self.assertTrue(headers["TIMESTAMP"].endswith("Z"))
        self.assertEqual(
            http.call_args.kwargs["json"],
            {
                "clientId": "client-id",
                "clientSecret": "client-secret",
                "grantType": "client_credentials",
            },
        )

    def test_session_without_token_is_refused(self, http):
        http.return_value = fake_response(data={"expiresIn": 1200})
        with self.assertRaises(AbdmError) as raised:
            client.get_session_token()
        self.assertEqual(raised.exception.status, 502)

    def test_request_carries_the_session_token(self, http):
        cache.set(client.SESSION_TOKEN_CACHE_KEY, "session-token")
        http.return_value = fake_response(data={"ABHANumber": "91-1234-5678-9012"})

        response = client.request(
            "GET", "/v3/profile/account", headers={"X-token": "Bearer x-token"}
        )

        self.assertEqual(response.data, {"ABHANumber": "91-1234-5678-9012"})
        method, url = http.call_args.args
        self.assertEqual(method, "GET")
        self.assertEqual(url, "https://abha.test/abha/api/v3/profile/account")
        headers = http.call_args.kwargs["headers"]
        self.assertEqual(headers["Authorization"], "Bearer session-token")
        self.assertEqual(headers["X-token"], "Bearer x-token")
        self.assertEqual(response.request_id, headers["REQUEST-ID"])
        self.assertEqual(http.call_args.kwargs["timeout"], 5)

    def test_error_response_is_normalised(self, http):
        cache.set(client.SESSION_TOKEN_CACHE_KEY, "session-token")
        http.return_value = fake_response(
            400, {"loginId": "Invalid LoginId", "timestamp": "2024-01-01"}
        )
        with self.assertRaises(AbdmError) as raised:
            client.request("POST", "/v3/profile/login/request/otp", json={})
        error = raised.exception
        self.assertEqual(
            (error.status, error.field, error.message),
            (400, "loginId", "Invalid LoginId"),
        )
        self.assertEqual(error.request_id, http.call_args.kwargs["headers"]["REQUEST-ID"])

    def test_gateway_token_error_drops_the_session_token(self, http):
        cache.set(client.SESSION_TOKEN_CACHE_KEY, "stale-token")
        http.return_value = fake_response(
            401, {"code": "900901", "message": "Invalid Credentials"}
        )
        with self.assertRaises(AbdmError) as raised:
            client.request("GET", "/v3/profile/account")
        self.assertEqual(raised.exception.code, "900901")
        self.assertIsNone(cache.get(client.SESSION_TOKEN_CACHE_KEY))
        # A credential problem is not retried.
        http.assert_called_once()

    def test_other_unauthorised_answers_keep_the_session_token(self, http):
