}

OAEP = "RSA/ECB/OAEPWithSHA-1AndMGF1Padding"
PKCS1 = "RSA/ECB/PKCS1Padding"


def fake_response(status_code=200, data=None, content_type="application/json"):
    response = mock.Mock()
    response.status_code = status_code
    response.headers = {"Content-Type": content_type}
    response.content = json.dumps(data).encode() if data is not None else b""
    response.json = lambda: json.loads(response.content)
    return response


def public_key_base64(private_key) -> str:
    der = private_key.public_key().public_bytes(
        serialization.Encoding.DER,
        serialization.PublicFormat.SubjectPublicKeyInfo,
    )
    return base64.b64encode(der).decode()


class AbdmCacheMixin:
    def setUp(self):
        super().setUp()
        cache.delete_many(
            [client.SESSION_TOKEN_CACHE_KEY, client.PUBLIC_CERTIFICATE_CACHE_KEY]
        )
        self.addCleanup(
            cache.delete_many,
            [client.SESSION_TOKEN_CACHE_KEY, client.PUBLIC_CERTIFICATE_CACHE_KEY],
        )


class NormaliseErrorTests(SimpleTestCase):
    def test_error_shapes(self):
        cases = [
            (
                {"error": {"code": "ABDM-1114", "message": "No account found"}},
                ("ABDM-1114", "No account found", ""),
            ),
            (
                [{"code": "ABDM-1006: ", "message": "Invalid Aadhaar"}],
                ("ABDM-1006", "Invalid Aadhaar", ""),
            ),
            (
                {"code": "900901", "message": "Invalid Credentials", "description": "x"},
                ("900901", "Invalid Credentials", ""),
            ),
            (
                {"code": "ABDM-9999", "description": "Only a description"},
                ("ABDM-9999", "Only a description", ""),
            ),
            (
                {"error": "Bad Request", "path": "/v3/x", "status": 400},
                ("", "Bad Request", ""),
            ),
            (
                {"otpValue": "Invalid OTP value", "timestamp": "2024-01-01"},
                ("", "Invalid OTP value", "otpValue"),
            ),
            (
                {"txnId": "Invalid Transaction Id", "timestamp": "2024-01-01"},
                ("", "Invalid Transaction Id", "txnId"),
            ),
            (
                {"txnId": "0f2a-77b1", "loginId": "Invalid LoginId"},
                ("", "Invalid LoginId", "loginId"),
            ),
        ]
        for data, expected in cases:
            with self.subTest(data=data):
                self.assertEqual(client.normalise_error(400, data), expected)

    def test_default_messages(self):
        self.assertEqual(
            client.normalise_error(429, None),
            ("", client.DEFAULT_ERROR_MESSAGES[429], ""),
        )
        self.assertEqual(
            client.normalise_error(500, None), ("", client.UNAVAILABLE_MESSAGE, "")
        )
        # An echoed transaction id alone is not an error message.
        self.assertEqual(
            client.normalise_error(400, {"txnId": "0f2a-77b1"}),
            ("", client.DEFAULT_ERROR_MESSAGES[400], ""),
        )


