    def test_binary_response_is_kept(self, http):
        cache.set(client.SESSION_TOKEN_CACHE_KEY, "session-token")
        png = b"\x89PNG\r\n\x1a\n"
        response = fake_response(content_type="image/png")
        response.content = png
        http.return_value = response

        result = client.request("GET", "/v3/profile/account/abha-card", accept="*/*")

