class AbhaCardTests(AbhaApiTestBase):
    def test_card_is_an_image(self):
        transaction_id = self.verified()
        card = self.abdm(
            "profile_card",
            return_value=AbdmResponse(
                200, None, PNG, "application/octet-stream", "request-id"
            ),
