                200, {"message": "x"}, b'{"message": "x"}', "application/json", "r"
            ),
        )
        response = self.get("card", transaction_id=transaction_id)
        self.assertEqual(response.status_code, status.HTTP_502_BAD_GATEWAY)

    def test_card_needs_a_verified_abha(self):
        transaction_id = self.login_otp_sent()
        response = self.get("card", transaction_id=transaction_id)
        self.assertEqual(self.error(response)["type"], "invalid_step")


