    """
    if patient_id:
        patient = get_object_or_404(Patient, external_id=patient_id)
        if not AuthorizationController.call("can_write_patient_obj", user, patient):
            raise PermissionDenied(
                "You do not have permission to update this patient."
            )
        return patient
    if not (
        user.is_superuser
        or AuthorizationController.call("can_create_patient", user)
    ):
        raise PermissionDenied("You do not have permission to register patients.")
    return None

def get_facility(self, user, facility_id) -> Facility | None:
    if not facility_id:
        return None
    facility = get_object_or_404(Facility, external_id=facility_id)
    if not (
        user.is_superuser
        or FacilityOrganizationUser.objects.filter(
            user=user, organization__facility=facility
        ).exists()
    ):
        raise PermissionDenied("You are not a member of this facility.")
    return facility

def can_link(self, user, patient: Patient, txn: AbhaTransaction) -> bool:
    if AuthorizationController.call("can_write_patient_obj", user, patient):
        return True
    # A desk registering a patient often has no write access to the record
    # it has just created. It may link the ABHA it verified for that
    # registration to the patient it created after starting the journey.
    return (
        not txn.patient_id
        and patient.created_by_id == user.id
        and patient.created_date.timestamp() >= txn.created_at
    )

# Journey helpers

def load(self, request, transaction_id, *steps) -> AbhaTransaction:
    txn = AbhaTransaction.load(transaction_id, request.user)
    if steps and txn.pending_step not in steps:
        raise JourneyError(
            "invalid_step",
            "This step is not available now. Please continue the ABHA "
            "journey from where it is.",
            step=journey_step(txn),
        )
    return txn

def load_from_query(self, request, *steps) -> AbhaTransaction:
    data = TransactionRequest.model_validate(
        {"transaction_id": request.query_params.get("transaction_id")}
    )
    return self.load(request, data.transaction_id, *steps)

