        {
            "suggestions": suggestions,
            "suffix": settings.ABDM_ABHA_ADDRESS_SUFFIX,
        }
    )

@action(detail=False, methods=["post"], url_path="create/address")
def create_address(self, request):
    data = AddressCreateRequest.model_validate(request.data)
    txn = self.load(request, data.transaction_id, "address")
    with default_field("abha_address"):
        result = abha.enrol_create_address(txn.abdm_txn_id, data.abha_address)
    txn.abdm_txn_id = result.get("txnId") or txn.abdm_txn_id
    address = abha.full_abha_address(
        result.get("preferredAbhaAddress") or data.abha_address
    )
    profile = dict(txn.profile or {})
    if txn.x_token:
        # The account as ABDM now holds it, with the new address.
        try:
            refreshed = abha.normalise_profile(abha.profile_account(txn.x_token))
        except AbdmError as e:
            logger.warning(
                "ABDM profile after address creation request_id=%s failed: %s",
                e.request_id,
                e.status,
            )
        else:
            profile.update(
                {key: value for key, value in refreshed.items() if value}
            )
    profile["abha_address"] = address
    if result.get("healthIdNumber"):
        profile["abha_number"] = abha.format_abha_number(
            result.get("healthIdNumber")
        )
    self.set_profile(txn, profile)
    txn.pending_step = "verified"
    return self.respond(txn)

@action(detail=False, methods=["post"], url_path="resend_otp")
def resend_otp(self, request):
    data = TransactionRequest.model_validate(request.data)
    txn = self.load(request, data.transaction_id, *OTP_STEPS)
    if not txn.resend_remaining():
        raise JourneyError(
            "resend_limit",
            "The OTP has been resent twice already. Please start again if it "
            "has not arrived.",
        )
    wait = txn.resend_wait()
    if wait:
        raise JourneyError(
            "resend_wait",
            f"Please wait {wait} seconds before asking for the OTP again.",
            available_in=wait,
        )
    step = txn.pending_step
    if step == "enrol":
        result = abha.enrol_request_otp(
            "aadhaar", txn.aadhaar_ciphertext, txn_id=txn.abdm_txn_id
        )
    elif step == "mobile_otp":
        result = abha.enrol_request_mobile_otp(
            txn.abdm_txn_id, txn.mobile_ciphertext
        )
    elif txn.login_family == "phr":
        # ABDM's ABHA address login takes no transaction to resend on.
        result = abha.phr_login_request_otp(txn.otp_system, txn.login_id)
    else:
        result = self.resend_login_otp(txn)
    self.otp_sent(txn, result, step, resend=True)
    return self.respond(txn)

@action(detail=False, methods=["get"])
def state(self, request):
    return Response(journey_state(self.load_from_query(request)))

@action(detail=False, methods=["get"])
def card(self, request):
    txn = self.load_from_query(request, "verified")
    if not txn.x_token:
        raise JourneyError(
            "card_unavailable", "The ABHA card is not available for this session."
        )
    if txn.login_family == "phr":
        response = abha.phr_card(txn.x_token)
    else:
        response = abha.profile_card(txn.x_token)
    content_type = response.content_type.split(";")[0].strip().lower()
    if content_type == "application/octet-stream":
        content_type = "image/png"
    if not response.content or not content_type.startswith("image/"):
        raise AbdmError(
            502,
            "ABDM did not return the ABHA card. Please try again.",
            request_id=response.request_id,
        )
    card = HttpResponse(response.content, content_type=content_type)
    card["Content-Disposition"] = 'inline; filename="abha-card.png"'
    return card

@action(detail=False, methods=["post"])
def link(self, request):
    data = LinkRequest.model_validate(request.data)
    txn = self.load(request, data.transaction_id, "verified")
    patient = get_object_or_404(Patient, external_id=data.patient)
    if txn.patient_id and txn.patient_id != str(patient.external_id):
        raise JourneyError(
            "patient_mismatch", "This ABHA was verified for a different patient."
        )
    if not self.can_link(request.user, patient, txn):
        raise PermissionDenied("You do not have permission to update this patient.")
    abha_number = _full_abha_number(txn.abha_number)
    if not (abha_number or txn.abha_address):
        raise JourneyError(
            "abha_missing", "ABDM did not return an ABHA number or address to link."
        )
    link_abha_to_patient(patient, abha_number, txn.abha_address)
    if txn.consent_id:
        AbhaConsent.objects.filter(external_id=txn.consent_id).update(
            patient=patient, abha_number=abha_number
        )
    txn.patient_id = str(patient.external_id)
    txn.save()
    return Response(
        {
            "patient": patient_summary(patient),
            "abha_number": abha_number,
            "abha_address": txn.abha_address,
        }
    )

