import i18n, { t } from "i18next";

import {
  AbhaIdentifierType,
  AbhaJourney,
  AbhaPatientSummary,
  AbhaStep,
} from "@/types/abdm/abha";
import { HTTPError } from "@/Utils/request/types";

export interface AbhaError {
  type: string;
  msg: string;
  field?: string;
  available_in?: number;
  patient?: AbhaPatientSummary | null;
  step?: AbhaStep;
  request_id?: string;
}

export interface AbhaStepProps {
  journey: AbhaJourney;
  onJourney: (journey: AbhaJourney) => void;
  onError: (error: unknown) => AbhaError[];
  onStartAgain: () => void;
}

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

/**
 * The ABHA API answers `{"errors": [{type, msg, loc?, ...}]}`; permission
 * refusals answer `{"detail": "..."}`. Every ABHA call is silent, so these are
 * rendered on the step in view rather than as toasts.
 */
export function parseAbhaErrors(error: unknown): AbhaError[] {
  if (error instanceof HTTPError) {
    const cause = error.cause;
    const errors = Array.isArray(cause?.errors)
      ? cause.errors.filter(isRecord)
      : [];
    if (errors.length) {
      return errors.map((item) => {
        const loc = Array.isArray(item.loc) ? item.loc : [];
        return {
          type: typeof item.type === "string" ? item.type : "error",
          msg:
            typeof item.msg === "string" && item.msg
              ? item.msg
              : t("abha_request_failed"),
          field: loc.length ? String(loc[0]).split(".")[0] : undefined,
          available_in:
            typeof item.available_in === "number"
              ? item.available_in
              : undefined,
          patient: isRecord(item.patient)
            ? (item.patient as unknown as AbhaPatientSummary)
            : null,
          step:
            typeof item.step === "string"
              ? (item.step as AbhaStep)
              : undefined,
          request_id:
            typeof item.request_id === "string" ? item.request_id : undefined,
        };
      });
    }
    if (typeof cause?.detail === "string") {
      return [{ type: "error", msg: cause.detail }];
    }
    return [{ type: "error", msg: t("abha_request_failed") }];
  }
  if (error instanceof Error && error.message === "Network Error") {
    return [{ type: "network", msg: t("abha_network_error") }];
  }
  return [{ type: "error", msg: t("abha_request_failed") }];
}

/**
 * Errors that name a field the step shows go under that field; the rest are
 * shown together at the foot of the step.
 */
export function splitAbhaErrors(errors: AbhaError[], fields: string[]) {
  const fieldErrors: Record<string, string> = {};
  const general: AbhaError[] = [];
  for (const error of errors) {
    if (error.field && fields.includes(error.field)) {
      fieldErrors[error.field] ??= error.msg;
    } else {
      general.push(error);
    }
  }
  return { fieldErrors, general };
}

const stripSeparators = (value: string) => value.replace(/[\s-]/g, "");

const LENIENT_ABHA_ADDRESS = /^[a-z0-9._-]+(@[a-z0-9._-]+)?$/;

/** The value sent for an identifier, cleaned the way the backend cleans it. */
export function cleanIdentifier(type: AbhaIdentifierType, value: string) {
  if (type === "abha_address") {
    return value.trim().toLowerCase();
  }
  return stripSeparators(value);
}

/**
 * Mirrors the backend's validation so that a malformed value is refused
 * before any request is made.
 */
export function validateIdentifier(
  type: AbhaIdentifierType,
  value: string,
): string | undefined {
  const cleaned = cleanIdentifier(type, value);
  switch (type) {
    case "aadhaar":
      return /^\d{12}$/.test(cleaned)
        ? undefined
        : t("abha_error_aadhaar_length");
    case "mobile":
      return /^\d{10}$/.test(cleaned)
        ? undefined
        : t("abha_error_mobile_length");
    case "abha_number":
      return /^\d{14}$/.test(cleaned)
        ? undefined
        : t("abha_error_abha_number_length");
    case "abha_address":
      return LENIENT_ABHA_ADDRESS.test(cleaned)
        ? undefined
        : t("abha_error_abha_address_invalid");
  }
}

export function validateMobile(value: string) {
  return /^\d{10}$/.test(stripSeparators(value))
    ? undefined
    : t("abha_error_mobile_length");
}

export function cleanMobile(value: string) {
  return stripSeparators(value);
}

export function validateOtp(value: string) {
  return /^\d{6}$/.test(value) ? undefined : t("abha_error_otp_length");
}

/** ABDM's rules for a new ABHA address, in the order they are listed. */
export const ABHA_ADDRESS_RULES = [
  "abha_address_rule_length",
  "abha_address_rule_characters",
  "abha_address_rule_one_each",
  "abha_address_rule_ends",
  "abha_address_rule_digit_start",
] as const;

/** A new ABHA address without its suffix, the way the backend expects it. */
export function cleanNewAbhaAddress(value: string, suffix: string) {
  const address = value.trim().toLowerCase();
  const ending = `@${suffix}`;
  return suffix && address.endsWith(ending)
    ? address.slice(0, -ending.length)
    : address;
}

export function validateNewAbhaAddress(
  value: string,
  suffix: string,
): string | undefined {
  const address = cleanNewAbhaAddress(value, suffix);
  const count = (character: string) => address.split(character).length - 1;
  if (address.length < 8 || address.length > 18) {
    return t("abha_address_rule_length");
  }
  if (!/^[a-z0-9._]+$/.test(address)) {
    return t("abha_address_rule_characters");
  }
  if (count(".") > 1 || count("_") > 1) {
    return t("abha_address_rule_one_each");
  }
  if (/^[._]/.test(address) || /[._]$/.test(address)) {
    return t("abha_address_rule_ends");
  }
  if (/^\d/.test(address)) {
    return t("abha_address_rule_digit_start");
  }
  return undefined;
}

/** A 10 digit Indian mobile from an E.164 phone number, if it is one. */
export function indianMobile(phoneNumber?: string | null) {
  const match = /^\+91(\d{10})$/.exec((phoneNumber ?? "").replace(/\s/g, ""));
  return match ? match[1] : "";
}

/** ABDM sends photos as bare base64; the type is read from the magic bytes. */
export function abhaPhotoUrl(photo?: string | null) {
  if (!photo) {
    return undefined;
  }
  if (photo.startsWith("data:")) {
    return photo;
  }
  const type = photo.startsWith("iVBOR") ? "image/png" : "image/jpeg";
  return `data:${type};base64,${photo}`;
}

/** The language the consent text was shown in, recorded with the consent. */
export function consentLanguage() {
  const language = i18n.language || "en";
  return i18n.exists("abha_consent_text", {
    lng: language,
    fallbackLng: false,
  })
    ? language
    : "en";
}

