import { HTTPError } from "@/Utils/request/types";

export interface AbhaError {
  type: string;
  msg: string;
  field?: string;
  available_in?: number;
  patient?: AbhaPatientSummary | null;
  step?: AbhaStep;
  request_id?: string;
}

export interface AbhaStepProps {
  journey: AbhaJourney;
  onJourney: (journey: AbhaJourney) => void;
  onError: (error: unknown) => AbhaError[];
  onStartAgain: () => void;
}

