import { CircleAlert } from "lucide-react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription } from "@/components/ui/alert";

import { AbhaError } from "@/components/Abdm/utils";

export default function AbhaErrors({ errors }: { errors: AbhaError[] }) {
  const { t } = useTranslation();

  if (!errors.length) {
    return null;
  }

  return (
    <Alert variant="destructive">
      <CircleAlert aria-hidden />
      <AlertDescription className="flex flex-col gap-1">
        {errors.map((error, index) => (
          <p key={index}>
            {error.msg}
            {error.request_id && (
              <span className="block text-xs text-gray-500">
                {t("abha_request_reference", { id: error.request_id })}
              </span>
            )}
          </p>
        ))}
      </AlertDescription>
    </Alert>
  );
}

import { ReactNode, useId } from "react";

import { cn } from "@/lib/utils";

import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";

interface AbhaChoiceOption {
  value: string;
  label: ReactNode;
  description?: ReactNode;
}

interface AbhaChoiceGroupProps {
  label: string;
  value: string;
  onValueChange: (value: string) => void;
  options: AbhaChoiceOption[];
  disabled?: boolean;
  className?: string;
}

/**
 * A radio group of bordered choices. Item ids are scoped to the group, so
 * several groups that share option values can be on screen together.
 */
export default function AbhaChoiceGroup({
  label,
  value,
  onValueChange,
  options,
  disabled,
  className,
}: AbhaChoiceGroupProps) {
  const id = useId();

  return (
    <RadioGroup
      aria-label={label}
      value={value}
      onValueChange={onValueChange}
      disabled={disabled}
      className={cn("grid gap-2 sm:grid-cols-2", className)}
    >
      {options.map((option) => {
        const itemId = `${id}-${option.value}`;
        return (
          <label
            key={option.value}
            htmlFor={itemId}
            className={cn(
              "flex cursor-pointer items-start gap-3 rounded-md border p-3 text-left transition-colors",
              value === option.value
                ? "border-primary-500 bg-primary-100"
                : "border-gray-300 bg-white hover:border-primary-500",
              disabled && "cursor-not-allowed opacity-60",
            )}
          >
            <RadioGroupItem
              id={itemId}
              value={option.value}
              className="mt-0.5 border-2 border-gray-300"
            />
            <span className="flex min-w-0 flex-1 flex-col gap-1">
              <span className="text-sm font-medium text-gray-900">
                {option.label}
              </span>
              {option.description && (
                <span className="text-xs text-gray-600">
                  {option.description}
                </span>
              )}
            </span>
          </label>
        );
      })}
    </RadioGroup>
  );
}

import { useId } from "react";
import { useTranslation } from "react-i18next";

import { Checkbox } from "@/components/ui/checkbox";

interface AbhaConsentProps {
  agreed: boolean;
  onAgreedChange: (agreed: boolean) => void;
  error?: string;
}

/**
 * ABDM's terms for using an Aadhaar number, shown verbatim. The person must
 * agree before their Aadhaar number is sent anywhere (CRT_ABHA_102).
 */
export default function AbhaConsent({
  agreed,
  onAgreedChange,
  error,
}: AbhaConsentProps) {
  const { t } = useTranslation();
  const id = useId();

  return (
    <div className="flex flex-col gap-2">
      <p id={`${id}-title`} className="text-sm font-semibold text-gray-900">
        {t("abha_consent_title")}
      </p>
      <div
        role="region"
        aria-labelledby={`${id}-title`}
        tabIndex={0}
        className="max-h-40 overflow-y-auto rounded-md border border-gray-200 bg-gray-50 p-3 text-xs leading-relaxed text-gray-700"
      >
        {t("abha_consent_text")}
      </div>
      <div className="flex items-start gap-2">
        <Checkbox
          id={id}
          checked={agreed}
          onCheckedChange={(checked) => onAgreedChange(checked === true)}
          aria-invalid={!!error}
          aria-describedby={error ? `${id}-error` : undefined}
          className="mt-0.5"
        />
        <label htmlFor={id} className="text-sm text-gray-900">
          {t("abha_consent_agree")}
        </label>
      </div>
      {error && (
        <p id={`${id}-error`} className="text-sm text-red-500">
          {error}
        </p>
      )}
    </div>
  );
}

