import { useMutation } from "@tanstack/react-query";
import { Info } from "lucide-react";
import { FormEvent, useId, useState } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

import AbhaChoiceGroup from "@/components/Abdm/AbhaChoiceGroup";
import AbhaConsent from "@/components/Abdm/AbhaConsent";
import AbhaErrors from "@/components/Abdm/AbhaErrors";
import {
  AbhaError,
  cleanIdentifier,
  consentLanguage,
  splitAbhaErrors,
  validateIdentifier,
} from "@/components/Abdm/utils";

import {
  ABHA_IDENTIFIER_TYPES,
  AbhaAddressSearchResponse,
  AbhaIdentifierType,
  AbhaJourney,
  AbhaOtpSystem,
} from "@/types/abdm/abha";
import abhaApi from "@/types/abdm/abhaApi";
import mutate from "@/Utils/request/mutate";

export interface AbhaLookup {
  type: AbhaIdentifierType;
  value: string;
}

interface AbhaIdentifyStepProps {
  initial: AbhaLookup;
  notice?: string;
  suffix: string;
  facilityId?: string;
  patientId?: string;
  onJourney: (journey: AbhaJourney, lookup: AbhaLookup) => void;
  onAddressNotFound: (lookup: AbhaLookup) => void;
  onError: (error: unknown) => AbhaError[];
  onCancel?: () => void;
}

const NUMERIC_TYPES: AbhaIdentifierType[] = ["aadhaar", "mobile", "abha_number"];

/**
 * One screen for both outcomes: every identifier starts on the login path and
 * ABDM's answer decides whether the person has an ABHA. Creation is offered
 * only after ABDM says nobody holds one.
 */
export default function AbhaIdentifyStep({
  initial,
  notice,
  suffix,
  facilityId,
  patientId,
  onJourney,
  onAddressNotFound,
  onError,
  onCancel,
}: AbhaIdentifyStepProps) {
  const { t } = useTranslation();
  const id = useId();
  const [type, setType] = useState<AbhaIdentifierType>(initial.type);
  const [value, setValue] = useState(initial.value);
  const [otpSystem, setOtpSystem] = useState<AbhaOtpSystem>("aadhaar");
  const [agreed, setAgreed] = useState(false);
  const [found, setFound] = useState<AbhaAddressSearchResponse | null>(null);
  const [errors, setErrors] = useState<AbhaError[]>([]);

  const { mutate: sendOtp, isPending: isSending } = useMutation({
    mutationFn: mutate(abhaApi.loginSendOtp, { silent: true }),
    onSuccess: (journey, request) =>
      onJourney(journey, { type: request.identifier_type, value }),
    onError: (error) => setErrors(onError(error)),
  });

  const { mutate: searchAddress, isPending: isSearching } = useMutation({
    mutationFn: mutate(abhaApi.addressSearch, { silent: true }),
    onSuccess: (result) => {
      if (!result.found) {
        onAddressNotFound({ type: "abha_address", value });
        return;
      }
      setFound(result);
      setOtpSystem(result.auth_methods[0] ?? "aadhaar");
    },
    onError: (error) => setErrors(onError(error)),
  });

  const isPending = isSending || isSearching;
  const { fieldErrors, general } = splitAbhaErrors(errors, [
    "value",
    "abha_address",
    "consent",
  ]);
  const valueError = fieldErrors.value ?? fieldErrors.abha_address;
  const cannotSendOtp = !!found && found.auth_methods.length === 0;

  const changeType = (next: string) => {
    const nextType = ABHA_IDENTIFIER_TYPES.find((item) => item === next);
    if (!nextType) {
      return;
    }
    setType(nextType);
    setValue("");
    setFound(null);
    setOtpSystem("aadhaar");
    setErrors([]);
  };

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    event.stopPropagation();

    const invalid = validateIdentifier(type, value);
    if (invalid) {
      setErrors([{ type: "validation_error", msg: invalid, field: "value" }]);
      return;
    }
    if (type === "aadhaar" && !agreed) {
      setErrors([
        {
          type: "consent_required",
          msg: t("abha_consent_required"),
          field: "consent",
        },
      ]);
      return;
    }
    setErrors([]);

    const cleaned = cleanIdentifier(type, value);
    if (type === "abha_address" && !found) {
      searchAddress({ abha_address: cleaned, patient: patientId });
      return;
    }
    sendOtp({
      identifier_type: type,
      value: found ? found.abha_address : cleaned,
      otp_system:
        type === "abha_number" || type === "abha_address"
          ? otpSystem
          : undefined,
      consent:
        type === "aadhaar"
          ? { agreed: true, language: consentLanguage() }
          : undefined,
      facility: facilityId,
      patient: patientId,
    });
  };

  const typeOptions = ABHA_IDENTIFIER_TYPES.map((item) => ({
    value: item,
    label: t(`abha_identifier__${item}`),
  }));

  const otpSystemOptions = (maskedMobile?: string) =>
    (found ? found.auth_methods : (["aadhaar", "abdm"] as AbhaOtpSystem[])).map(
      (system) => ({
        value: system,
        label: t(`abha_otp_system__${system}`),
        description:
          system === "abdm" && maskedMobile
            ? t("abha_otp_to_masked_mobile", { mobile: maskedMobile })
            : t(`abha_otp_system_description__${system}`),
      }),
    );

  const valueId = `${id}-value`;
  const hintId = `${id}-hint`;
  const errorId = `${id}-error`;

  return (
    <form className="flex flex-col gap-5" onSubmit={submit} noValidate>
      {notice && (
        <Alert>
          <Info aria-hidden />
          <AlertDescription>{notice}</AlertDescription>
        </Alert>
      )}

      <p className="text-sm text-gray-700">{t("abha_identify_description")}</p>

      <div className="flex flex-col gap-2">
        <span className="text-sm font-medium text-gray-900">
          {t("abha_identify_with")}
        </span>
        <AbhaChoiceGroup
          label={t("abha_identify_with")}
          value={type}
          onValueChange={changeType}
          options={typeOptions}
          disabled={isPending}
          className="sm:grid-cols-4"
        />
      </div>

      <div className="flex flex-col gap-2">
        <Label htmlFor={valueId}>{t(`abha_identifier__${type}`)}</Label>
        <div className="flex items-stretch">
          <Input
            id={valueId}
            value={value}
            onChange={(event) => {
              setValue(event.target.value);
              setFound(null);
              if (valueError) {
                setErrors([]);
              }
            }}
            placeholder={t(`abha_identifier_placeholder__${type}`)}
            inputMode={NUMERIC_TYPES.includes(type) ? "numeric" : "text"}
            autoComplete="off"
            autoCapitalize="none"
            spellCheck={false}
            aria-invalid={!!valueError}
            aria-describedby={valueError ? `${hintId} ${errorId}` : hintId}
            className={
              type === "abha_address" && suffix ? "rounded-r-none" : undefined
            }
          />
          {type === "abha_address" && suffix && (
            <span className="flex items-center rounded-r-md border border-l-0 border-gray-300 bg-gray-50 px-3 text-sm text-gray-600">
              {`@${suffix}`}
            </span>
          )}
        </div>
        <p id={hintId} className="text-xs text-gray-500">
          {t(`abha_identifier_hint__${type}`, { suffix })}
        </p>
        {valueError && (
          <p id={errorId} className="text-sm text-red-500">
            {valueError}
          </p>
        )}
      </div>

      {type === "abha_number" && (
        <div className="flex flex-col gap-2">
          <span className="text-sm font-medium text-gray-900">
            {t("abha_otp_system")}
          </span>
          <AbhaChoiceGroup
            label={t("abha_otp_system")}
            value={otpSystem}
            onValueChange={(next) => setOtpSystem(next as AbhaOtpSystem)}
            options={otpSystemOptions()}
            disabled={isPending}
          />
        </div>
      )}

      {type === "abha_address" && found && (
        <div className="flex flex-col gap-2 rounded-md border border-gray-200 bg-gray-50 p-3">
          <p className="text-sm text-gray-900">
            {t("abha_address_found", { address: found.abha_address })}
          </p>
          {cannotSendOtp && (
            <p className="text-sm text-red-500">
              {t("abha_address_no_otp_method")}
            </p>
          )}
          {found.auth_methods.length > 1 && (
            <AbhaChoiceGroup
              label={t("abha_otp_system")}
              value={otpSystem}
              onValueChange={(next) => setOtpSystem(next as AbhaOtpSystem)}
              options={otpSystemOptions(found.masked_mobile)}
              disabled={isPending}
            />
          )}
          {found.auth_methods.length === 1 && (
            <p className="text-xs text-gray-600">
              {otpSystemOptions(found.masked_mobile)[0].description}
            </p>
          )}
        </div>
      )}

      {type === "aadhaar" && (
        <AbhaConsent
          agreed={agreed}
          onAgreedChange={(next) => {
            setAgreed(next);
            if (fieldErrors.consent) {
              setErrors([]);
            }
          }}
          error={fieldErrors.consent}
        />
      )}

      <AbhaErrors errors={general} />

      <div className="flex flex-wrap justify-end gap-2">
        {onCancel && (
          <Button type="button" variant="ghost" onClick={onCancel}>
            {t("abha_not_now")}
          </Button>
        )}
        <Button
          type="submit"
          variant="primary"
          disabled={isPending || cannotSendOtp}
        >
          {type === "abha_address" && !found
            ? t("abha_find_address")
            : t("send_otp")}
        </Button>
      </div>
    </form>
  );
}

