import { HttpMethod, Type } from "@/Utils/request/types";

import {
  AbhaAddressCreateRequest,
  AbhaAddressSearchRequest,
  AbhaAddressSearchResponse,
  AbhaAddressSuggestions,
  AbhaConfig,
  AbhaEnrolVerifyRequest,
  AbhaJourney,
  AbhaLinkRequest,
  AbhaLinkResponse,
  AbhaLoginSendOtpRequest,
  AbhaOtpVerifyRequest,
  AbhaTransactionRequest,
  AbhaVerifyUserRequest,
} from "./abha";

const BASE = "/api/v1/abdm/abha";

export default {
  config: {
    path: `${BASE}/config/`,
    method: HttpMethod.GET,
    TRes: Type<AbhaConfig>(),
  },
  state: {
    path: `${BASE}/state/`,
    method: HttpMethod.GET,
    TRes: Type<AbhaJourney>(),
  },
  card: {
    path: `${BASE}/card/`,
    method: HttpMethod.GET,
    TRes: Type<Blob>(),
  },
  loginSendOtp: {
    path: `${BASE}/login/send_otp/`,
    method: HttpMethod.POST,
    TBody: Type<AbhaLoginSendOtpRequest>(),
    TRes: Type<AbhaJourney>(),
  },
  loginVerifyOtp: {
    path: `${BASE}/login/verify_otp/`,
    method: HttpMethod.POST,
    TBody: Type<AbhaOtpVerifyRequest>(),
    TRes: Type<AbhaJourney>(),
  },
  loginVerifyUser: {
    path: `${BASE}/login/verify_user/`,
    method: HttpMethod.POST,
    TBody: Type<AbhaVerifyUserRequest>(),
    TRes: Type<AbhaJourney>(),
  },
  addressSearch: {
    path: `${BASE}/abha_address/search/`,
    method: HttpMethod.POST,
    TBody: Type<AbhaAddressSearchRequest>(),
    TRes: Type<AbhaAddressSearchResponse>(),
  },
  createSendOtp: {
    path: `${BASE}/create/send_otp/`,
    method: HttpMethod.POST,
    TBody: Type<AbhaTransactionRequest>(),
    TRes: Type<AbhaJourney>(),
  },
  createVerifyOtp: {
    path: `${BASE}/create/verify_otp/`,
    method: HttpMethod.POST,
    TBody: Type<AbhaEnrolVerifyRequest>(),
    TRes: Type<AbhaJourney>(),
  },
  createSendMobileOtp: {
    path: `${BASE}/create/send_mobile_otp/`,
    method: HttpMethod.POST,
    TBody: Type<AbhaTransactionRequest>(),
    TRes: Type<AbhaJourney>(),
  },
  createVerifyMobileOtp: {
    path: `${BASE}/create/verify_mobile_otp/`,
    method: HttpMethod.POST,
    TBody: Type<AbhaOtpVerifyRequest>(),
    TRes: Type<AbhaJourney>(),
  },
  addressSuggestions: {
    path: `${BASE}/create/address_suggestions/`,
    method: HttpMethod.GET,
    TRes: Type<AbhaAddressSuggestions>(),
  },
  createAddress: {
    path: `${BASE}/create/address/`,
    method: HttpMethod.POST,
    TBody: Type<AbhaAddressCreateRequest>(),
    TRes: Type<AbhaJourney>(),
  },
  resendOtp: {
    path: `${BASE}/resend_otp/`,
    method: HttpMethod.POST,
    TBody: Type<AbhaTransactionRequest>(),
    TRes: Type<AbhaJourney>(),
  },
  link: {
    path: `${BASE}/link/`,
    method: HttpMethod.POST,
    TBody: Type<AbhaLinkRequest>(),
    TRes: Type<AbhaLinkResponse>(),
  },
} as const;

