@action(detail=False, methods=["get"])
def config(self, request):
    return Response(
        {
            "enabled": settings.ABDM_ENABLED,
            "abha_address_suffix": settings.ABDM_ABHA_ADDRESS_SUFFIX,
        }
    )

@action(detail=False, methods=["post"], url_path="login/send_otp")
def login_send_otp(self, request):
    data = LoginSendOtpRequest.model_validate(request.data)
    patient = self.authorize_start(request.user, data.patient)
    facility = self.get_facility(request.user, data.facility)
    txn = AbhaTransaction(
        user_id=request.user.id,
        facility_id=facility.id if facility else None,
        patient_id=str(patient.external_id) if patient else None,
        identifier_type=data.identifier_type,
        otp_system=data.resolved_otp_system(),
    )
    if data.identifier_type == "aadhaar":
        if not (data.consent and data.consent.agreed):
            raise JourneyError(
                "consent_required",
                "The person must agree to ABDM's terms before their Aadhaar "
                "number is used.",
                field="consent",
            )
        consent = AbhaConsent.objects.create(
            language=data.consent.language,
            facility=facility,
            patient=patient,
            created_by=request.user,
            updated_by=request.user,
        )
        txn.consent_id = str(consent.external_id)
    if data.identifier_type == "mobile":
        txn.masked_mobile = abha.mask_mobile(data.value)

    txn.login_id = encrypt(data.value)
    if data.identifier_type == "aadhaar":
        txn.aadhaar_ciphertext = txn.login_id
    try:
        with default_field("value"):
            if data.identifier_type == "abha_address":
                txn.login_family = "phr"
                txn.scope = abha.ADDRESS_LOGIN_SCOPES[txn.otp_system]
                result = abha.phr_login_request_otp(txn.otp_system, txn.login_id)
            else:
                txn.scope = abha.LOGIN_SCOPES[(txn.identifier_type, txn.otp_system)]
                result = abha.login_request_otp(
                    txn.identifier_type, txn.otp_system, txn.login_id
                )
    except AbdmError as e:
        if not is_not_found(e):
            raise
        return self.not_found(txn, e.message)
    self.otp_sent(txn, result, "login")
    return self.respond(txn)

@action(detail=False, methods=["post"], url_path="login/verify_otp")
def login_verify_otp(self, request):
    data = OtpVerifyRequest.model_validate(request.data)
    txn = self.load(request, data.transaction_id, "login")
    try:
        with default_field("otp"):
            if txn.login_family == "phr":
                result = abha.phr_login_verify(txn.scope, txn.abdm_txn_id, data.otp)
            else:
                result = abha.login_verify(txn.scope, txn.abdm_txn_id, data.otp)
    except AbdmError as e:
        if not is_not_found(e):
            raise
        return self.not_found(txn, e.message)
    txn.abdm_txn_id = result.get("txnId") or txn.abdm_txn_id
    txn.otp_sent_at = None

    if txn.login_family == "phr":
        txn.x_token = (result.get("tokens") or {}).get("token") or ""
        return self.complete_login(txn)
    if result.get("refreshToken"):
        # Only an X-token comes with a refresh token.
        txn.x_token = result.get("token") or ""
        return self.complete_login(txn)

    # A T-token: the account has to be chosen, even when there is one.
    txn.t_token = result.get("token") or ""
    accounts = [a for a in result.get("accounts") or [] if isinstance(a, dict)]
    txn.account_numbers = [str(a.get("ABHANumber") or "") for a in accounts]
    txn.accounts = [_account_summary(a) for a in accounts]
    if not accounts:
        return self.not_found(txn)
    if len(accounts) == 1:
        return self.select_account(txn, 0)
    txn.pending_step = "choose_account"
    return self.respond(txn)

@action(detail=False, methods=["post"], url_path="login/verify_user")
def login_verify_user(self, request):
    data = VerifyUserRequest.model_validate(request.data)
    txn = self.load(request, data.transaction_id, "choose_account")
    if data.account >= len(txn.account_numbers):
        raise JourneyError(
            "invalid_account", "Choose one of the listed accounts.", field="account"
        )
    return self.select_account(txn, data.account)

@action(detail=False, methods=["post"], url_path="abha_address/search")
def abha_address_search(self, request):
    data = AddressSearchRequest.model_validate(request.data)
    self.authorize_start(request.user, data.patient)
    try:
        with default_field("abha_address"):
            result = abha.phr_search(data.abha_address)
    except AbdmError as e:
        if not is_not_found(e):
            raise
        result = None
    if not result:
        return Response(
            {
                "found": False,
                "abha_address": data.abha_address,
                "auth_methods": [],
                "masked_mobile": "",
                "status": "",
            }
        )
    blocked = set(result.get("blockedAuthMethods") or [])
    auth_methods = []
    for method in result.get("authMethods") or []:
        otp_system = abha.ADDRESS_AUTH_METHODS.get(method)
        if otp_system and method not in blocked and otp_system not in auth_methods:
            auth_methods.append(otp_system)
    # The name is not shown before the person has proved it is theirs.
    return Response(
        {
            "found": True,
            "abha_address": abha.full_abha_address(result.get("abhaAddress"))
            or data.abha_address,
            "auth_methods": auth_methods,
            "masked_mobile": str(result.get("mobile") or ""),
            "status": result.get("status") or "",
        }
    )

@action(detail=False, methods=["post"], url_path="create/send_otp")
def create_send_otp(self, request):
    data = TransactionRequest.model_validate(request.data)
    txn = self.load(request, data.transaction_id, "not_found")
    if not (txn.aadhaar_not_found and txn.aadhaar_ciphertext):
        raise JourneyError(
            "create_not_allowed",
            "An ABHA is created only after a lookup by Aadhaar number finds none.",
        )
    result = abha.enrol_request_otp("aadhaar", txn.aadhaar_ciphertext)
    txn.flow = "create"
    txn.scope = abha.ENROL_SCOPE
    txn.otp_system = abha.OTP_SYSTEM_AADHAAR
    txn.masked_mobile = ""
    self.otp_sent(txn, result, "enrol")
    return self.respond(txn)

@action(detail=False, methods=["post"], url_path="create/verify_otp")
def create_verify_otp(self, request):
    data = EnrolVerifyRequest.model_validate(request.data)
    txn = self.load(request, data.transaction_id, "enrol")
    with default_field("otp"):
        result = abha.enrol_by_aadhaar(txn.abdm_txn_id, data.otp, data.mobile)
    txn.abdm_txn_id = result.get("txnId") or txn.abdm_txn_id
    txn.otp_sent_at = None
    tokens = result.get("tokens") or result.get("jwtResponse") or {}
    txn.x_token = tokens.get("token") or ""
    txn.is_new = bool(result.get("isNew"))
    if not txn.is_new:
        # The Aadhaar already held an ABHA, and this OTP has opened it.
        return self.complete_login(txn)

    raw_profile = result.get("ABHAProfile") or {}
    profile = abha.normalise_profile(raw_profile)
    txn.masked_mobile = abha.mask_mobile(data.mobile)
    if abha.mobile_verification_required(raw_profile.get("mobile"), data.mobile):
        txn.mobile_ciphertext = encrypt(data.mobile)
        txn.pending_step = "mobile_verify"
    else:
        profile["mobile"] = data.mobile
        profile["masked_mobile"] = txn.masked_mobile
        txn.pending_step = "address"
    self.set_profile(txn, profile)
    return self.respond(txn)

@action(detail=False, methods=["post"], url_path="create/send_mobile_otp")
def create_send_mobile_otp(self, request):
    data = TransactionRequest.model_validate(request.data)
    txn = self.load(request, data.transaction_id, "mobile_verify")
    with default_field("mobile"):
        result = abha.enrol_request_mobile_otp(
            txn.abdm_txn_id, txn.mobile_ciphertext
        )
    self.otp_sent(txn, result, "mobile_otp")
    return self.respond(txn)

@action(detail=False, methods=["post"], url_path="create/verify_mobile_otp")
def create_verify_mobile_otp(self, request):
    data = OtpVerifyRequest.model_validate(request.data)
    txn = self.load(request, data.transaction_id, "mobile_otp")
    with default_field("otp"):
        result = abha.enrol_verify_mobile(txn.abdm_txn_id, data.otp)
    txn.abdm_txn_id = result.get("txnId") or txn.abdm_txn_id
    txn.otp_sent_at = None
    txn.profile = {**(txn.profile or {}), "masked_mobile": txn.masked_mobile}
    txn.pending_step = "address"
    return self.respond(txn)

@action(detail=False, methods=["get"], url_path="create/address_suggestions")
def create_address_suggestions(self, request):
    txn = self.load_from_query(request, "address")
    result = abha.enrol_suggestions(txn.abdm_txn_id)
    txn.abdm_txn_id = result.get("txnId") or txn.abdm_txn_id
    txn.save()
    suggestions = [
        str(item).strip().lower()
        for item in result.get("abhaAddressList") or []
        if isinstance(item, str) and item.strip()
    ]
    return Response(
        {
            "suggestions": suggestions,
            "suffix": settings.ABDM_ABHA_ADDRESS_SUFFIX,
        }
    )

@action(detail=False, methods=["post"], url_path="create/address")
def create_address(self, request):
    data = AddressCreateRequest.model_validate(request.data)
    txn = self.load(request, data.transaction_id, "address")
    with default_field("abha_address"):
        result = abha.enrol_create_address(txn.abdm_txn_id, data.abha_address)
    txn.abdm_txn_id = result.get("txnId") or txn.abdm_txn_id
    address = abha.full_abha_address(
        result.get("preferredAbhaAddress") or data.abha_address
    )
    profile = dict(txn.profile or {})
    if txn.x_token:
        # The account as ABDM now holds it, with the new address.
        try:
            refreshed = abha.normalise_profile(abha.profile_account(txn.x_token))
        except AbdmError as e:
            logger.warning(
                "ABDM profile after address creation request_id=%s failed: %s",
                e.request_id,
                e.status,
            )
        else:
            profile.update(
                {key: value for key, value in refreshed.items() if value}
            )
    profile["abha_address"] = address
    if result.get("healthIdNumber"):
        profile["abha_number"] = abha.format_abha_number(
            result.get("healthIdNumber")
        )
    self.set_profile(txn, profile)
    txn.pending_step = "verified"
    return self.respond(txn)

