class AbhaViewSet(GenericViewSet):
    def get_exception_handler(self):
        return abdm_exception_handler

    def initial(self, request, *args, **kwargs):
        super().initial(request, *args, **kwargs)
        if self.action != "config" and not settings.ABDM_ENABLED:
            raise AbdmError(
                503,
                "ABDM is not enabled on this CARE server.",
                code="abdm_disabled",
            )

    def finalize_response(self, request, response, *args, **kwargs):
        response = super().finalize_response(request, response, *args, **kwargs)
        # Responses carry identity details and must not be cached.
        response["Cache-Control"] = "no-store"
        return response

    # Authorization

    def authorize_start(self, user, patient_id) -> Patient | None:
        """
        A journey is for an existing patient the user may update, or for
        registering a new patient.
        """
        if patient_id:
            patient = get_object_or_404(Patient, external_id=patient_id)
            if not AuthorizationController.call("can_write_patient_obj", user, patient):
                raise PermissionDenied(
                    "You do not have permission to update this patient."
                )
            return patient
        if not (
            user.is_superuser
            or AuthorizationController.call("can_create_patient", user)
        ):
            raise PermissionDenied("You do not have permission to register patients.")
        return None

    def get_facility(self, user, facility_id) -> Facility | None:
        if not facility_id:
            return None
        facility = get_object_or_404(Facility, external_id=facility_id)
        if not (
            user.is_superuser
            or FacilityOrganizationUser.objects.filter(
                user=user, organization__facility=facility
            ).exists()
        ):
            raise PermissionDenied("You are not a member of this facility.")
        return facility

    def can_link(self, user, patient: Patient, txn: AbhaTransaction) -> bool:
        if AuthorizationController.call("can_write_patient_obj", user, patient):
            return True
        # A desk registering a patient often has no write access to the record
        # it has just created. It may link the ABHA it verified for that
        # registration to the patient it created after starting the journey.
        return (
            not txn.patient_id
            and patient.created_by_id == user.id
            and patient.created_date.timestamp() >= txn.created_at
        )

    # Journey helpers

    def load(self, request, transaction_id, *steps) -> AbhaTransaction:
        txn = AbhaTransaction.load(transaction_id, request.user)
        if steps and txn.pending_step not in steps:
            raise JourneyError(
                "invalid_step",
                "This step is not available now. Please continue the ABHA "
                "journey from where it is.",
                step=journey_step(txn),
            )
        return txn

    def load_from_query(self, request, *steps) -> AbhaTransaction:
        data = TransactionRequest.model_validate(
            {"transaction_id": request.query_params.get("transaction_id")}
        )
        return self.load(request, data.transaction_id, *steps)

    def respond(self, txn: AbhaTransaction) -> Response:
        txn.save()
        return Response(journey_state(txn))

    def not_found(self, txn: AbhaTransaction, message: str = "") -> Response:
        txn.pending_step = "not_found"
        txn.message = message
        txn.otp_sent_at = None
        # Only a lookup by Aadhaar number can lead to creation: the ABHA is
        # made from that Aadhaar, which was just shown to hold none.
        txn.aadhaar_not_found = txn.identifier_type == "aadhaar"
        return self.respond(txn)

    def set_profile(self, txn: AbhaTransaction, profile: dict) -> None:
        txn.profile = profile
        txn.abha_number = profile.get("abha_number") or ""
        txn.abha_address = profile.get("abha_address") or ""

    def complete_login(self, txn: AbhaTransaction) -> Response:
        if not txn.x_token:
            raise AbdmError(502, "ABDM did not open the ABHA. Please try again.")
        if txn.login_family == "phr":
            raw = abha.phr_profile(txn.x_token)
        else:
            raw = abha.profile_account(txn.x_token)
        self.set_profile(txn, abha.normalise_profile(raw))
        txn.t_token = ""
        txn.pending_step = "verified"
        return self.respond(txn)

    def select_account(self, txn: AbhaTransaction, index: int) -> Response:
        with default_field("account"):
            result = abha.login_verify_user(
                txn.t_token, txn.abdm_txn_id, txn.account_numbers[index]
            )
        txn.x_token = result.get("token") or ""
        return self.complete_login(txn)

    def otp_sent(self, txn: AbhaTransaction, result: dict, step: str, **kwargs):
        txn.otp_sent(result, **kwargs)
        txn.pending_step = step
        txn.masked_mobile = (
            abha.masked_mobile_from_message(txn.message) or txn.masked_mobile
        )

    def resend_login_otp(self, txn: AbhaTransaction) -> dict:
        try:
            return abha.login_request_otp(
                txn.identifier_type,
                txn.otp_system,
                txn.login_id,
                txn_id=txn.abdm_txn_id,
            )
        except AbdmError as e:
            refused_transaction = e.field == "txnId" or "transaction" in (
                e.message.lower()
            )
            if e.status != 400 or not refused_transaction:  # noqa: PLR2004
                raise
        # ABDM's login does not document a resend; if it will not reuse the
        # transaction, the OTP is requested afresh.
        logger.info("ABDM refused a login OTP resend on the same transaction")
        return abha.login_request_otp(txn.identifier_type, txn.otp_system, txn.login_id)

    # Endpoints

