import { useMutation } from "@tanstack/react-query";
import { REGEXP_ONLY_DIGITS } from "input-otp";
import { FormEvent, useEffect, useId, useState } from "react";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  InputOTP,
  InputOTPGroup,
  InputOTPSlot,
} from "@/components/ui/input-otp";
import { Label } from "@/components/ui/label";

import AbhaErrors from "@/components/Abdm/AbhaErrors";
import {
  AbhaError,
  AbhaStepProps,
  cleanMobile,
  splitAbhaErrors,
  validateMobile,
  validateOtp,
} from "@/components/Abdm/utils";

import { AbhaJourney } from "@/types/abdm/abha";
import abhaApi from "@/types/abdm/abhaApi";
import { callApi } from "@/Utils/request/query";

const OTP_LENGTH = 6;

export interface AbhaMobileSuggestion {
  mobile: string;
  source: "lookup" | "patient";
}

interface AbhaOtpStepProps extends AbhaStepProps {
  // A mobile CARE already has for the person, offered as the ABHA's
  // communication mobile when an ABHA is created.
  suggestedMobile?: AbhaMobileSuggestion;
}

function otpSentKey(journey: AbhaJourney) {
  if (journey.otp_for === "mobile") {
    return "abha_otp_sent__communication";
  }
  if (journey.otp_for === "login" && journey.identifier_type === "mobile") {
    return "abha_otp_sent__mobile";
  }
  if (journey.otp_for === "login" && journey.otp_system === "abdm") {
    return "abha_otp_sent__abha";
  }
  return "abha_otp_sent__aadhaar";
}

export default function AbhaOtpStep({
  journey,
  onJourney,
  onError,
  onStartAgain,
  suggestedMobile,
}: AbhaOtpStepProps) {
  const { t } = useTranslation();
  const id = useId();
  const isEnrol = journey.otp_for === "enrol";
  const [otp, setOtp] = useState("");
  const [mobile, setMobile] = useState(suggestedMobile?.mobile ?? "");
  const [errors, setErrors] = useState<AbhaError[]>([]);
  const [secondsLeft, setSecondsLeft] = useState(
    journey.resend?.available_in ?? 0,
  );

  useEffect(() => {
    if (secondsLeft <= 0) {
      return;
    }
    const timer = setTimeout(() => setSecondsLeft((left) => left - 1), 1000);
    return () => clearTimeout(timer);
  }, [secondsLeft]);

  const showErrors = (error: unknown) => {
    const next = onError(error);
    if (next.some((item) => item.field === "otp")) {
      setOtp("");
    }
    setErrors(next);
  };

  const { mutate: verify, isPending: isVerifying } = useMutation({
    mutationFn: ({ otp, mobile }: { otp: string; mobile: string }) => {
      const transaction_id = journey.transaction_id;
      const options = { silent: true } as const;
      if (journey.otp_for === "enrol") {
        return callApi(abhaApi.createVerifyOtp, {
          ...options,
          body: { transaction_id, otp, mobile },
        });
      }
      if (journey.otp_for === "mobile") {
        return callApi(abhaApi.createVerifyMobileOtp, {
          ...options,
          body: { transaction_id, otp },
        });
      }
      return callApi(abhaApi.loginVerifyOtp, {
        ...options,
        body: { transaction_id, otp },
      });
    },
    onSuccess: onJourney,
    onError: showErrors,
  });

  const { mutate: resend, isPending: isResending } = useMutation({
    mutationFn: () =>
      callApi(abhaApi.resendOtp, {
        body: { transaction_id: journey.transaction_id },
        silent: true,
      }),
    onSuccess: (next) => {
      setOtp("");
      setErrors([]);
      setSecondsLeft(next.resend?.available_in ?? 0);
      onJourney(next);
    },
    onError: (error) => {
      const next = onError(error);
      const wait = next.find((item) => item.available_in);
      if (wait?.available_in) {
        setSecondsLeft(wait.available_in);
      }
      setErrors(next);
    },
  });

  const { fieldErrors, general } = splitAbhaErrors(errors, ["otp", "mobile"]);

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    event.stopPropagation();
    const invalid: AbhaError[] = [];
    const otpError = validateOtp(otp);
    if (otpError) {
      invalid.push({ type: "validation_error", msg: otpError, field: "otp" });
    }
    const mobileError = isEnrol ? validateMobile(mobile) : undefined;
    if (mobileError) {
      invalid.push({
        type: "validation_error",
        msg: mobileError,
        field: "mobile",
      });
    }
    setErrors(invalid);
    if (!invalid.length) {
      verify({ otp, mobile: cleanMobile(mobile) });
    }
  };

  const remaining = journey.resend?.remaining ?? 0;
  const isPending = isVerifying || isResending;
  const otpId = `${id}-otp`;
  const mobileId = `${id}-mobile`;

  return (
    <form className="flex flex-col gap-5" onSubmit={submit} noValidate>
      <div className="flex flex-col gap-1">
        <p className="text-base font-semibold text-gray-900">
          {t(
            journey.otp_for === "mobile"
              ? "abha_verify_communication_mobile"
              : isEnrol
                ? "abha_verify_aadhaar_otp"
                : "abha_verify_otp_title",
          )}
        </p>
        <p className="text-sm text-gray-700" aria-live="polite">
          {t(otpSentKey(journey))}
          {journey.masked_mobile && (
            <span className="ml-1 font-medium text-gray-900">
              {t("abha_otp_sent_to", { mobile: journey.masked_mobile })}
            </span>
          )}
        </p>
      </div>

      <div className="flex flex-col gap-2">
        <Label htmlFor={otpId}>{t("abha_otp_label")}</Label>
        <InputOTP
          id={otpId}
          maxLength={OTP_LENGTH}
          value={otp}
          onChange={(value) => {
            setOtp(value);
            if (fieldErrors.otp) {
              setErrors([]);
            }
          }}
          pattern={REGEXP_ONLY_DIGITS}
          autoFocus
          disabled={isVerifying}
          aria-invalid={!!fieldErrors.otp}
          aria-describedby={fieldErrors.otp ? `${otpId}-error` : undefined}
        >
          <InputOTPGroup>
            {Array.from({ length: OTP_LENGTH }).map((_, index) => (
              <InputOTPSlot
                key={index}
                index={index}
                className={cn(fieldErrors.otp && "border-red-500")}
              />
            ))}
          </InputOTPGroup>
        </InputOTP>
        {fieldErrors.otp && (
          <p id={`${otpId}-error`} className="text-sm text-red-500">
            {fieldErrors.otp}
          </p>
        )}
        <div className="flex flex-wrap items-center gap-2 text-sm text-gray-600">
          {remaining > 0 ? (
            secondsLeft > 0 ? (
              <span aria-live="polite">
                {t("abha_resend_in", { seconds: secondsLeft })}
              </span>
            ) : (
              <Button
                type="button"
                variant="link"
                className="h-auto p-0"
                onClick={() => resend()}
                disabled={isPending}
              >
                {t("resend_otp")}
              </Button>
            )
          ) : (
            <span>{t("abha_resend_limit_reached")}</span>
          )}
          {remaining > 0 && (
            <span className="text-xs text-gray-500">
              {t("abha_resends_remaining", { count: remaining })}
            </span>
          )}
        </div>
      </div>

      {isEnrol && (
        <div className="flex flex-col gap-2">
          <Label htmlFor={mobileId}>{t("abha_communication_mobile")}</Label>
          <Input
            id={mobileId}
            value={mobile}
            onChange={(event) => {
              setMobile(event.target.value);
              if (fieldErrors.mobile) {
                setErrors([]);
              }
            }}
            inputMode="numeric"
            autoComplete="tel-national"
            maxLength={12}
            placeholder={t("abha_identifier_placeholder__mobile")}
            aria-invalid={!!fieldErrors.mobile}
            aria-describedby={`${mobileId}-hint${
              fieldErrors.mobile ? ` ${mobileId}-error` : ""
            }`}
          />
          <p id={`${mobileId}-hint`} className="text-xs text-gray-500">
            {t("abha_communication_mobile_hint")}
            {suggestedMobile && mobile === suggestedMobile.mobile && (
              <span className="block">
                {t(`abha_mobile_prefilled__${suggestedMobile.source}`)}
              </span>
            )}
          </p>
          {fieldErrors.mobile && (
            <p id={`${mobileId}-error`} className="text-sm text-red-500">
              {fieldErrors.mobile}
            </p>
          )}
        </div>
      )}

      <AbhaErrors errors={general} />

      <div className="flex flex-wrap justify-end gap-2">
        <Button
          type="button"
          variant="ghost"
          onClick={onStartAgain}
          disabled={isVerifying}
        >
          {t("abha_start_again")}
        </Button>
        <Button type="submit" variant="primary" disabled={isPending}>
          {t("verify")}
        </Button>
      </div>
    </form>
  );
}

import { useMutation } from "@tanstack/react-query";
import { REGEXP_ONLY_DIGITS } from "input-otp";
import { FormEvent, useEffect, useId, useState } from "react";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  InputOTP,
  InputOTPGroup,
  InputOTPSlot,
} from "@/components/ui/input-otp";
import { Label } from "@/components/ui/label";

import AbhaErrors from "@/components/Abdm/AbhaErrors";
import {
  AbhaError,
  AbhaStepProps,
  cleanMobile,
  splitAbhaErrors,
  validateMobile,
  validateOtp,
} from "@/components/Abdm/utils";

import { AbhaJourney } from "@/types/abdm/abha";
import abhaApi from "@/types/abdm/abhaApi";
import { callApi } from "@/Utils/request/query";

const OTP_LENGTH = 6;

export interface AbhaMobileSuggestion {
  mobile: string;
  source: "lookup" | "patient";
}

interface AbhaOtpStepProps extends AbhaStepProps {
  // A mobile CARE already has for the person, offered as the ABHA's
  // communication mobile when an ABHA is created.
  suggestedMobile?: AbhaMobileSuggestion;
}

function otpSentKey(journey: AbhaJourney) {
  if (journey.otp_for === "mobile") {
    return "abha_otp_sent__communication";
  }
  if (journey.otp_for === "login" && journey.identifier_type === "mobile") {
    return "abha_otp_sent__mobile";
  }
  if (journey.otp_for === "login" && journey.otp_system === "abdm") {
    return "abha_otp_sent__abha";
  }
  return "abha_otp_sent__aadhaar";
}

export default function AbhaOtpStep({
  journey,
  onJourney,
  onError,
  onStartAgain,
  suggestedMobile,
}: AbhaOtpStepProps) {
  const { t } = useTranslation();
  const id = useId();
  const isEnrol = journey.otp_for === "enrol";
  const [otp, setOtp] = useState("");
  const [mobile, setMobile] = useState(suggestedMobile?.mobile ?? "");
  const [errors, setErrors] = useState<AbhaError[]>([]);
  const [secondsLeft, setSecondsLeft] = useState(
    journey.resend?.available_in ?? 0,
  );

  useEffect(() => {
    if (secondsLeft <= 0) {
      return;
    }
    const timer = setTimeout(() => setSecondsLeft((left) => left - 1), 1000);
    return () => clearTimeout(timer);
  }, [secondsLeft]);

  const showErrors = (error: unknown) => {
    const next = onError(error);
    if (next.some((item) => item.field === "otp")) {
      setOtp("");
    }
    setErrors(next);
  };

  const { mutate: verify, isPending: isVerifying } = useMutation({
    mutationFn: ({ otp, mobile }: { otp: string; mobile: string }) => {
      const transaction_id = journey.transaction_id;
      const options = { silent: true } as const;
      if (journey.otp_for === "enrol") {
        return callApi(abhaApi.createVerifyOtp, {
          ...options,
          body: { transaction_id, otp, mobile },
        });
      }
      if (journey.otp_for === "mobile") {
        return callApi(abhaApi.createVerifyMobileOtp, {
          ...options,
          body: { transaction_id, otp },
        });
      }
      return callApi(abhaApi.loginVerifyOtp, {
        ...options,
        body: { transaction_id, otp },
      });
    },
    onSuccess: onJourney,
    onError: showErrors,
  });

  const { mutate: resend, isPending: isResending } = useMutation({
    mutationFn: () =>
      callApi(abhaApi.resendOtp, {
        body: { transaction_id: journey.transaction_id },
        silent: true,
      }),
    onSuccess: (next) => {
      setOtp("");
      setErrors([]);
      setSecondsLeft(next.resend?.available_in ?? 0);
      onJourney(next);
    },
    onError: (error) => {
      const next = onError(error);
      const wait = next.find((item) => item.available_in);
      if (wait?.available_in) {
        setSecondsLeft(wait.available_in);
      }
      setErrors(next);
    },
  });

  const { fieldErrors, general } = splitAbhaErrors(errors, ["otp", "mobile"]);

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    event.stopPropagation();
    const invalid: AbhaError[] = [];
    const otpError = validateOtp(otp);
    if (otpError) {
      invalid.push({ type: "validation_error", msg: otpError, field: "otp" });
    }
    const mobileError = isEnrol ? validateMobile(mobile) : undefined;
    if (mobileError) {
      invalid.push({
        type: "validation_error",
        msg: mobileError,
        field: "mobile",
      });
    }
    setErrors(invalid);
    if (!invalid.length) {
      verify({ otp, mobile: cleanMobile(mobile) });
    }
  };

  const remaining = journey.resend?.remaining ?? 0;
  const isPending = isVerifying || isResending;
  const otpId = `${id}-otp`;
  const mobileId = `${id}-mobile`;

  return (
    <form className="flex flex-col gap-5" onSubmit={submit} noValidate>
      <div className="flex flex-col gap-1">
        <p className="text-base font-semibold text-gray-900">
          {t(
            journey.otp_for === "mobile"
              ? "abha_verify_communication_mobile"
              : isEnrol
                ? "abha_verify_aadhaar_otp"
                : "abha_verify_otp_title",
          )}
        </p>
        <p className="text-sm text-gray-700" aria-live="polite">
          {t(otpSentKey(journey))}
          {journey.masked_mobile && (
            <span className="ml-1 font-medium text-gray-900">
              {t("abha_otp_sent_to", { mobile: journey.masked_mobile })}
            </span>
          )}
        </p>
      </div>

      <div className="flex flex-col gap-2">
        <Label htmlFor={otpId}>{t("abha_otp_label")}</Label>
        <InputOTP
          id={otpId}
          maxLength={OTP_LENGTH}
          value={otp}
          onChange={(value) => {
            setOtp(value);
            if (fieldErrors.otp) {
              setErrors([]);
            }
          }}
          pattern={REGEXP_ONLY_DIGITS}
          autoFocus
          disabled={isVerifying}
          aria-invalid={!!fieldErrors.otp}
          aria-describedby={fieldErrors.otp ? `${otpId}-error` : undefined}
        >
          <InputOTPGroup>
            {Array.from({ length: OTP_LENGTH }).map((_, index) => (
              <InputOTPSlot
                key={index}
                index={index}
                className={cn(fieldErrors.otp && "border-red-500")}
              />
            ))}
          </InputOTPGroup>
        </InputOTP>
        {fieldErrors.otp && (
          <p id={`${otpId}-error`} className="text-sm text-red-500">
            {fieldErrors.otp}
          </p>
        )}
        <div className="flex flex-wrap items-center gap-2 text-sm text-gray-600">
          {remaining > 0 ? (
            secondsLeft > 0 ? (
              <span aria-live="polite">
                {t("abha_resend_in", { seconds: secondsLeft })}
              </span>
            ) : (
              <Button
                type="button"
                variant="link"
                className="h-auto p-0"
                onClick={() => resend()}
                disabled={isPending}
              >
                {t("resend_otp")}
              </Button>
            )
          ) : (
            <span>{t("abha_resend_limit_reached")}</span>
          )}
          {remaining > 0 && (
            <span className="text-xs text-gray-500">
              {t("abha_resends_remaining", { count: remaining })}
            </span>
          )}
        </div>
      </div>

      {isEnrol && (
        <div className="flex flex-col gap-2">
          <Label htmlFor={mobileId}>{t("abha_communication_mobile")}</Label>
          <Input
            id={mobileId}
            value={mobile}
            onChange={(event) => {
              setMobile(event.target.value);
              if (fieldErrors.mobile) {
                setErrors([]);
              }
            }}
            inputMode="numeric"
            autoComplete="tel-national"
            maxLength={12}
            placeholder={t("abha_identifier_placeholder__mobile")}
            aria-invalid={!!fieldErrors.mobile}
            aria-describedby={`${mobileId}-hint${
              fieldErrors.mobile ? ` ${mobileId}-error` : ""
            }`}
          />
          <p id={`${mobileId}-hint`} className="text-xs text-gray-500">
            {t("abha_communication_mobile_hint")}
            {suggestedMobile && mobile === suggestedMobile.mobile && (
              <span className="block">
                {t(`abha_mobile_prefilled__${suggestedMobile.source}`)}
              </span>
            )}
          </p>
          {fieldErrors.mobile && (
            <p id={`${mobileId}-error`} className="text-sm text-red-500">
              {fieldErrors.mobile}
            </p>
          )}
        </div>
      )}

      <AbhaErrors errors={general} />

      <div className="flex flex-wrap justify-end gap-2">
        <Button
          type="button"
          variant="ghost"
          onClick={onStartAgain}
          disabled={isVerifying}
        >
          {t("abha_start_again")}
        </Button>
        <Button type="submit" variant="primary" disabled={isPending}>
          {t("verify")}
        </Button>
      </div>
    </form>
  );
}

