import { useMutation } from "@tanstack/react-query";
import { FormEvent, useState } from "react";
import { useTranslation } from "react-i18next";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";

import { Avatar } from "@/components/Common/Avatar";

import AbhaChoiceGroup from "@/components/Abdm/AbhaChoiceGroup";
import AbhaErrors from "@/components/Abdm/AbhaErrors";
import {
  AbhaError,
  AbhaStepProps,
  abhaPhotoUrl,
} from "@/components/Abdm/utils";

import { AbhaAccount } from "@/types/abdm/abha";
import abhaApi from "@/types/abdm/abhaApi";
import mutate from "@/Utils/request/mutate";

function AccountSummary({ account }: { account: AbhaAccount }) {
  const { t } = useTranslation();
  const details = [
    account.gender && t(`GENDER__${account.gender}`),
    account.year_of_birth &&
      t("abha_year_of_birth_short", { year: account.year_of_birth }),
  ].filter(Boolean);

  return (
    <span className="flex items-start gap-3">
      <Avatar
        name={account.name || account.abha_address || "-"}
        imageUrl={abhaPhotoUrl(account.photo)}
        className="size-10 shrink-0"
      />
      <span className="flex min-w-0 flex-col gap-1">
        <span className="font-semibold">{account.name || "-"}</span>
        {details.length > 0 && (
          <span className="text-xs font-normal text-gray-600">
            {details.join(" · ")}
          </span>
        )}
        {account.abha_number && (
          <span className="text-xs font-normal break-all text-gray-700">
            {t("abha_number")}: {account.abha_number}
          </span>
        )}
        {account.abha_address && (
          <span className="text-xs font-normal break-all text-gray-700">
            {t("abha_address")}: {account.abha_address}
          </span>
        )}
        <span className="flex flex-wrap gap-1">
          {account.kyc_verified && (
            <Badge variant="green" size="xs">
              {t("abha_kyc_verified")}
            </Badge>
          )}
          {account.linked_patient && (
            <Badge variant="yellow" size="xs">
              {t("abha_linked_to", { name: account.linked_patient.name })}
            </Badge>
          )}
        </span>
      </span>
    </span>
  );
}

/**
 * A mobile number or Aadhaar can hold several ABHAs. The person says which one
 * is theirs; nothing is chosen for them.
 */
export default function AbhaAccountChooser({
  journey,
  onJourney,
  onError,
  onStartAgain,
}: AbhaStepProps) {
  const { t } = useTranslation();
  const [selected, setSelected] = useState("");
  const [errors, setErrors] = useState<AbhaError[]>([]);

  const { mutate: verifyUser, isPending } = useMutation({
    mutationFn: mutate(abhaApi.loginVerifyUser, { silent: true }),
    onSuccess: onJourney,
    onError: (error) => setErrors(onError(error)),
  });

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    event.stopPropagation();
    if (selected === "") {
      setErrors([{ type: "validation_error", msg: t("abha_choose_account") }]);
      return;
    }
    setErrors([]);
    verifyUser({
      transaction_id: journey.transaction_id,
      account: Number(selected),
    });
  };

  return (
    <form className="flex flex-col gap-5" onSubmit={submit} noValidate>
      <div className="flex flex-col gap-1">
        <p className="text-base font-semibold text-gray-900">
          {t("abha_choose_account_title")}
        </p>
        <p className="text-sm text-gray-700">
          {t("abha_choose_account_description", {
            count: journey.accounts.length,
          })}
        </p>
      </div>

      <AbhaChoiceGroup
        label={t("abha_choose_account_title")}
        value={selected}
        onValueChange={(value) => {
          setSelected(value);
          setErrors([]);
        }}
        options={journey.accounts.map((account) => ({
          value: String(account.index),
          label: <AccountSummary account={account} />,
        }))}
        disabled={isPending}
        className="sm:grid-cols-1"
      />

      <AbhaErrors errors={errors} />

      <div className="flex flex-wrap justify-end gap-2">
        <Button
          type="button"
          variant="ghost"
          onClick={onStartAgain}
          disabled={isPending}
        >
          {t("abha_start_again")}
        </Button>
        <Button type="submit" variant="primary" disabled={isPending}>
          {t("continue")}
        </Button>
      </div>
    </form>
  );
}

