import { useMutation } from "@tanstack/react-query";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";

import AbhaErrors from "@/components/Abdm/AbhaErrors";
import { AbhaError, AbhaStepProps } from "@/components/Abdm/utils";

import abhaApi from "@/types/abdm/abhaApi";
import mutate from "@/Utils/request/mutate";

/**
 * The communication mobile given while creating the ABHA is not the one linked
 * with the Aadhaar, so ABDM has it verified before it is added to the ABHA.
 */
export default function AbhaMobileVerifyStep({
  journey,
  onJourney,
  onError,
  onStartAgain,
}: AbhaStepProps) {
  const { t } = useTranslation();
  const [errors, setErrors] = useState<AbhaError[]>([]);

  const { mutate: sendMobileOtp, isPending } = useMutation({
    mutationFn: mutate(abhaApi.createSendMobileOtp, { silent: true }),
    onSuccess: onJourney,
    onError: (error) => setErrors(onError(error)),
  });

  return (
    <div className="flex flex-col gap-5">
      <div className="flex flex-col gap-1">
        <p className="text-base font-semibold text-gray-900">
          {t("abha_verify_communication_mobile")}
        </p>
        {journey.abha_number && (
          <p className="text-sm text-gray-700">
            {t("abha_number_created", { number: journey.abha_number })}
          </p>
        )}
        <p className="text-sm text-gray-700">
          {t("abha_mobile_verify_description", {
            mobile: journey.masked_mobile,
          })}
        </p>
      </div>

      <AbhaErrors errors={errors} />

      <div className="flex flex-wrap justify-end gap-2">
        <Button
          type="button"
          variant="ghost"
          onClick={onStartAgain}
          disabled={isPending}
        >
          {t("abha_start_again")}
        </Button>
        <Button
          type="button"
          variant="primary"
          onClick={() =>
            sendMobileOtp({ transaction_id: journey.transaction_id })
          }
          disabled={isPending}
        >
          {t("send_otp")}
        </Button>
      </div>
    </div>
  );
}

