  });

  const { fieldErrors, general } = splitAbhaErrors(errors, ["abha_address"]);
  const checks = checkNewAbhaAddress(address, addressSuffix);
  const typed = address.trim() !== "";

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    event.stopPropagation();
    const invalid = validateNewAbhaAddress(address, addressSuffix);
    if (invalid) {
      setErrors([
        { type: "validation_error", msg: invalid, field: "abha_address" },
      ]);
      return;
    }
    setErrors([]);
    createAddress({
      transaction_id: journey.transaction_id,
      abha_address: cleanNewAbhaAddress(address, addressSuffix),
    });
