            {fieldErrors.abha_address}
          </p>
        )}
        <ul id={rulesId} className="flex flex-col gap-1 text-xs text-gray-600">
          {checks.map(({ rule, passes }) => {
            const Icon = !typed ? Circle : passes ? CircleCheck : CircleX;
            return (
              <li key={rule} className="flex items-center gap-2">
                <Icon
                  aria-hidden
                  className={cn(
                    "size-3.5 shrink-0",
                    !typed
                      ? "text-gray-400"
                      : passes
                        ? "text-green-600"
                        : "text-red-500",
                  )}
                />
                <span>{t(rule)}</span>
                {typed && (
                  <span className="sr-only">
                    {t(passes ? "abha_rule_met" : "abha_rule_not_met")}
                  </span>
                )}
              </li>
            );
          })}
        </ul>
      </div>

      <AbhaErrors errors={general} />

      <div className="flex flex-wrap justify-end gap-2">
        <Button
          type="button"
          variant="ghost"
          onClick={onStartAgain}
          disabled={isPending}
        >
          {t("abha_start_again")}
        </Button>
        <Button type="submit" variant="primary" disabled={isPending}>
          {t("abha_create_address")}
        </Button>
      </div>
    </form>
  );
}

