+import { useQuery } from "@tanstack/react-query";
+import { Download } from "lucide-react";
+import { useTranslation } from "react-i18next";
+
+import { Button } from "@/components/ui/button";
+import {
+  Dialog,
+  DialogContent,
+  DialogDescription,
+  DialogFooter,
+  DialogHeader,
+  DialogTitle,
+} from "@/components/ui/dialog";
+
+import AbhaErrors from "@/components/Abdm/AbhaErrors";
+import { parseAbhaErrors } from "@/components/Abdm/utils";
+
+import abhaApi from "@/types/abdm/abhaApi";
+import { callApi } from "@/Utils/request/query";
+
+const CARD_EXTENSIONS: Record<string, string> = {
+  "image/png": "png",
+  "image/jpeg": "jpg",
+  "image/jpg": "jpg",
+  "image/svg+xml": "svg",
+};
+
+const readAsDataUrl = (blob: Blob) =>
+  new Promise<string>((resolve, reject) => {
+    const reader = new FileReader();
+    reader.onload = () => resolve(String(reader.result));
+    reader.onerror = () => reject(reader.error);
+    reader.readAsDataURL(blob);
+  });
+
+interface AbhaCardDialogProps {
+  transactionId: string;
+  open: boolean;
+  onOpenChange: (open: boolean) => void;
+}
+
+/**
+ * The ABHA card is fetched from ABDM with the verified session's token; it is
+ * not kept once the journey is over.
+ */
+export default function AbhaCardDialog({
+  transactionId,
+  open,
+  onOpenChange,
+}: AbhaCardDialogProps) {
+  const { t } = useTranslation();
+
+  const { data, error, isFetching, refetch } = useQuery({
+    queryKey: ["abdm", "abha-card", transactionId],
+    queryFn: async ({ signal }) => {
+      const card = await callApi(abhaApi.card, {
+        queryParams: { transaction_id: transactionId },
+        silent: true,
+        signal,
+      });
+      if (!(card instanceof Blob)) {
+        throw new Error(t("abha_card_unavailable"));
+      }
+      return {
+        url: await readAsDataUrl(card),
+        extension: CARD_EXTENSIONS[card.type] ?? "png",
+      };
+    },
+    enabled: open,
+    staleTime: Infinity,
+    gcTime: 0,
+    retry: false,
+  });
+
+  const errors =
+    error instanceof Error && error.message === t("abha_card_unavailable")
+      ? [{ type: "error", msg: error.message }]
+      : error
+        ? parseAbhaErrors(error)
+        : [];
+
+  return (
+    <Dialog open={open} onOpenChange={onOpenChange}>
+      <DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-2xl">
+        <DialogHeader>
+          <DialogTitle>{t("abha_card")}</DialogTitle>
+          <DialogDescription>{t("abha_card_description")}</DialogDescription>
+        </DialogHeader>
+        {isFetching && !data && (
+          <p className="text-sm text-gray-500" aria-live="polite">
+            {t("abha_card_loading")}
+          </p>
+        )}
+        {data && (
+          <img
+            src={data.url}
+            alt={t("abha_card")}
+            className="w-full rounded-md border border-gray-200"
+          />
+        )}
+        <AbhaErrors errors={errors} />
+        <DialogFooter className="gap-2">
+          {error && (
+            <Button
+              type="button"
+              variant="outline"
+              onClick={() => refetch()}
+              disabled={isFetching}
+            >
+              {t("try_again")}
+            </Button>
+          )}
+          {data && (
+            <Button variant="primary" asChild>
+              <a href={data.url} download={`abha-card.${data.extension}`}>
+                <Download aria-hidden />
+                {t("download")}
+              </a>
+            </Button>
+          )}
+          <Button
+            type="button"
+            variant="outline"
+            onClick={() => onOpenChange(false)}
+          >
+            {t("close")}
+          </Button>
+        </DialogFooter>
+      </DialogContent>
+    </Dialog>
+  );
+}

