            }
            setJourney(next);
          }}
          onAddressNotFound={(nextLookup) => {
            setLookup(nextLookup);
            setAddressNotFound(nextLookup);
          }}
          onError={handleError}
          onCancel={onCancel}
        />
      );
    }

    switch (journey.step) {
      case "otp":
        return (
          <AbhaOtpStep
            key={`${journey.transaction_id}:${journey.otp_for}`}
            journey={journey}
            suggestedMobile={suggestedMobile}
            {...stepProps}
          />
        );
      case "choose_account":
        return (
          <AbhaAccountChooser
            key={journey.transaction_id}
            journey={journey}
            {...stepProps}
          />
        );
      case "not_found":
        return (
          <AbhaNotFoundStep
            journey={journey}
            lookup={
              lookup ?? { type: journey.identifier_type, value: "" }
            }
            onJourney={setJourney}
            onError={handleError}
            onCreateWithAadhaar={() =>
              restart(t("abha_enter_aadhaar_to_create"), {
                type: "aadhaar",
                value: "",
              })
            }
            onTryAnother={() => restart()}
          />
        );
      case "mobile_verify":
        return <AbhaMobileVerifyStep journey={journey} {...stepProps} />;
      case "address":
        return (
          <AbhaAddressStep
            key={journey.transaction_id}
            journey={journey}
            suffix={suffix}
            {...stepProps}
          />
        );
      case "verified":
        return (
          <AbhaVerifiedStep
            journey={journey}
            patientId={patientId}
            renderActions={renderActions}
            onStartAgain={stepProps.onStartAgain}
          />
        );
    }
  };

  return (
    <div
      ref={containerRef}
      tabIndex={-1}
      className="outline-none"
      aria-label={t("abha_journey_label")}
      role="group"
    >
      {renderStep()}
    </div>
  );
}

