const tagIds = form.watch("tags") || [];
const selectedTags = useTagConfigs({ ids: tagIds, facilityId })
  .map(({ data }) => data)
  .filter(Boolean) as TagConfig[];

return (
  <>
    <FormField
      control={form.control}
      name="name"
      render={({ field }) => (
        <FormItem>
          <FormLabel aria-required>{t("name")}</FormLabel>
          <FormControl>
            <Input
              autoFocus
              tabIndex={0}
              placeholder={t("type_name")}
              {...field}
              value={field.value ?? ""}
            />
          </FormControl>
          <FormMessage />
        </FormItem>
      )}
    />

    <div className="flex flex-col gap-4">
      <FormField
        control={form.control}
        name="phone_number"
        render={({ field }) => (
          <FormItem>
            <FormLabel aria-required>{t("phone_number")}</FormLabel>
            <FormControl>
              <PhoneInput
                {...field}
                placeholder={t("enter_phone_number")}
                onChange={(value) => {
                  field.onChange(value);
                  if (
                    form.getValues(
                      "emergency_phone_number_same_as_phone_number",
                    )
                  ) {
                    form.setValue("emergency_phone_number", value || "", {
                      shouldDirty: true,
                    });
                  }
                }}
              />
            </FormControl>
            <FormMessage />
          </FormItem>
        )}
      />
      <FormField
        control={form.control}
        name="emergency_phone_number_same_as_phone_number"
        render={({ field }) => (
          <FormItem className="flex items-center gap-2">
            <FormControl>
              <Checkbox
                checked={!field.value}
                onCheckedChange={(value) => field.onChange(!value)}
              />
            </FormControl>
            <FormLabel>
              {t("use_different_emergency_contact_number")}
            </FormLabel>
            <FormMessage />
          </FormItem>
        )}
      />
    </div>

    {!form.watch("emergency_phone_number_same_as_phone_number") && (
      <FormField
        control={form.control}
        name="emergency_phone_number"
        render={({ field }) => (
          <FormItem>
            <FormLabel aria-required>{t("emergency_phone_number")}</FormLabel>
            <FormControl>
              <PhoneInput {...field} placeholder={t("enter_phone_number")} />
            </FormControl>
            <FormMessage />
          </FormItem>
        )}
      />
    )}

    <FormField
      control={form.control}
      name="gender"
      render={({ field }) => (
        <FormItem>
          <FormLabel aria-required>{t("sex")}</FormLabel>
          <FormControl>
            <RadioInput
              {...field}
              onValueChange={field.onChange}
