                   aria-invalid={!!fieldState.error}
                   required={minGeoOrganizationLevelsRequired == null}
                   requiredDepth={minGeoOrganizationLevelsRequired}
                   value={form.watch("_selected_levels")[0] ?? null}
                   onChange={(organization) => {
                     form.setValue(
