// The identifier systems the backend links an ABHA to a patient under. Their
// configs are instance level and auto maintained, so they are read from
// `instance_identifiers` by system rather than through the identifier configs.
export const ABHA_NUMBER_SYSTEM = "system.care.ohc.network/abha-number";
export const ABHA_ADDRESS_SYSTEM = "system.care.ohc.network/abha-address";

export const ABHA_IDENTIFIER_TYPES = [
  "aadhaar",
  "mobile",
  "abha_number",
  "abha_address",
] as const;

export type AbhaIdentifierType = (typeof ABHA_IDENTIFIER_TYPES)[number];

// "aadhaar" sends the OTP to the mobile linked with Aadhaar, "abdm" to the
// mobile linked with the ABHA.
export type AbhaOtpSystem = "aadhaar" | "abdm";

export type AbhaStep =
  | "otp"
  | "choose_account"
  | "not_found"
  | "mobile_verify"
  | "address"
  | "verified";

export type AbhaOtpFor = "login" | "enrol" | "mobile";

export interface AbhaConfig {
  enabled: boolean;
  abha_address_suffix: string;
}

export interface AbhaPatientSummary {
  id: string;
  name: string;
}

export interface AbhaProfile {
  abha_number: string;
  abha_address: string;
  name: string;
  first_name: string;
  middle_name: string;
  last_name: string;
  gender: "male" | "female" | "transgender" | "non_binary" | "";
  date_of_birth: string | null;
  year_of_birth: number | null;
  mobile: string;
  masked_mobile: string;
  email: string;
  address: string;
  district: string;
  state: string;
  pincode: string;
  photo: string;
  kyc_verified: boolean;
  status: string;
}

export interface AbhaAccount
  extends Pick<
    AbhaProfile,
    | "abha_number"
    | "abha_address"
    | "name"
    | "gender"
    | "year_of_birth"
    | "photo"
    | "status"
    | "kyc_verified"
  > {
  index: number;
  linked_patient: AbhaPatientSummary | null;
}

export interface AbhaJourney {
  transaction_id: string;
  step: AbhaStep;
  otp_for: AbhaOtpFor | null;
  flow: "login" | "create";
  identifier_type: AbhaIdentifierType;
  otp_system: AbhaOtpSystem;
  masked_mobile: string;
  message: string;
  resend: { remaining: number; available_in: number } | null;
  accounts: AbhaAccount[];
  create_allowed: boolean;
  profile: AbhaProfile | null;
  abha_number: string;
  abha_address: string;
  is_new: boolean;
  linked_patient: AbhaPatientSummary | null;
}

export interface AbhaLoginSendOtpRequest {
  identifier_type: AbhaIdentifierType;
  value: string;
  otp_system?: AbhaOtpSystem;
  consent?: { agreed: boolean; language: string };
  facility?: string;
  patient?: string;
}

export interface AbhaTransactionRequest {
  transaction_id: string;
}

export interface AbhaOtpVerifyRequest extends AbhaTransactionRequest {
  otp: string;
}

export interface AbhaEnrolVerifyRequest extends AbhaOtpVerifyRequest {
  mobile: string;
}

export interface AbhaVerifyUserRequest extends AbhaTransactionRequest {
  account: number;
}

export interface AbhaAddressSearchRequest {
  abha_address: string;
  patient?: string;
}

export interface AbhaAddressSearchResponse {
  found: boolean;
  abha_address: string;
  auth_methods: AbhaOtpSystem[];
  masked_mobile: string;
  status: string;
}

export interface AbhaAddressSuggestions {
  suggestions: string[];
  suffix: string;
}

export interface AbhaAddressCreateRequest extends AbhaTransactionRequest {
  abha_address: string;
}

export interface AbhaLinkRequest extends AbhaTransactionRequest {
  patient: string;
}

export interface AbhaLinkResponse {
  patient: AbhaPatientSummary;
  abha_number: string;
  abha_address: string;
}

