import dayjs from "dayjs";
import { CircleCheck, IdCard } from "lucide-react";
import { navigate } from "raviger";
import { ReactNode, useState } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";

import { Avatar } from "@/components/Common/Avatar";

import AbhaCardDialog from "@/components/Abdm/AbhaCardDialog";
import { AbhaStepProps, abhaPhotoUrl } from "@/components/Abdm/utils";

import { AbhaJourney } from "@/types/abdm/abha";

interface AbhaVerifiedStepProps
  extends Pick<AbhaStepProps, "journey" | "onStartAgain"> {
  patientId?: string;
  renderActions: (journey: AbhaJourney) => ReactNode;
}

function Detail({ label, value }: { label: string; value?: ReactNode }) {
  if (!value) {
    return null;
  }
  return (
    <div className="flex flex-col">
      <dt className="text-xs text-gray-500">{label}</dt>
      <dd className="text-sm font-medium break-all text-gray-900">{value}</dd>
    </div>
  );
}

export default function AbhaVerifiedStep({
  journey,
  onStartAgain,
  patientId,
  renderActions,
}: AbhaVerifiedStepProps) {
  const { t } = useTranslation();
  const [cardOpen, setCardOpen] = useState(false);
  const profile = journey.profile;
  const abhaNumber = profile?.abha_number || journey.abha_number;
  const abhaAddress = profile?.abha_address || journey.abha_address;
  const linked = journey.linked_patient;
  const linkedElsewhere = !!linked && linked.id !== patientId;
  const linkedHere = !!linked && linked.id === patientId;

  const address = profile
    ? [profile.address, profile.district, profile.state, profile.pincode]
        .filter(Boolean)
        .join(", ")
    : "";

  return (
    <div className="flex flex-col gap-5">
      <div className="flex items-center gap-2">
        <CircleCheck className="size-5 text-green-600" aria-hidden />
        <p className="text-base font-semibold text-gray-900" aria-live="polite">
          {t(journey.is_new ? "abha_created" : "abha_verified")}
        </p>
      </div>

      <div className="flex flex-col gap-4 rounded-md border border-gray-200 bg-white p-4 sm:flex-row">
        <Avatar
          name={profile?.name || abhaAddress || "-"}
          imageUrl={abhaPhotoUrl(profile?.photo)}
          className="size-16 shrink-0"
        />
        <dl className="grid flex-1 gap-3 sm:grid-cols-2">
          <Detail label={t("name")} value={profile?.name} />
          <Detail
            label={t("sex")}
            value={profile?.gender && t(`GENDER__${profile.gender}`)}
          />
          {profile?.date_of_birth ? (
            <Detail
              label={t("date_of_birth")}
              value={dayjs(profile.date_of_birth).format("DD MMM YYYY")}
            />
          ) : (
            <Detail label={t("year_of_birth")} value={profile?.year_of_birth} />
          )}
          <Detail
            label={t("mobile_number")}
            value={profile?.mobile || profile?.masked_mobile}
          />
          <Detail label={t("abha_number")} value={abhaNumber} />
          <Detail label={t("abha_address")} value={abhaAddress} />
          <div className="sm:col-span-2">
            <Detail label={t("address")} value={address} />
          </div>
          {profile?.kyc_verified && (
            <div>
              <Badge variant="green" size="xs">
                {t("abha_kyc_verified")}
              </Badge>
            </div>
          )}
        </dl>
      </div>

      <div>
        <Button
          type="button"
          variant="outline"
          onClick={() => setCardOpen(true)}
        >
          <IdCard aria-hidden />
          {t("abha_view_card")}
        </Button>
      </div>
      <AbhaCardDialog
        transactionId={journey.transaction_id}
        open={cardOpen}
        onOpenChange={setCardOpen}
      />

      {linkedElsewhere && (
        <Alert variant="destructive">
          <AlertTitle>{t("abha_already_linked_title")}</AlertTitle>
          <AlertDescription className="flex flex-col items-start gap-2">
            <p>{t("abha_already_linked", { name: linked.name })}</p>
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={() => navigate(`/patient/${linked.id}`)}
            >
              {t("abha_open_patient_record")}
            </Button>
          </AlertDescription>
        </Alert>
      )}
      {linkedHere && (
        <Alert>
          <CircleCheck aria-hidden />
          <AlertDescription>{t("abha_linked_to_this_patient")}</AlertDescription>
        </Alert>
      )}

      <div className="flex flex-wrap justify-end gap-2">
        <Button type="button" variant="ghost" onClick={onStartAgain}>
          {t("abha_start_again")}
        </Button>
        {!linked && renderActions(journey)}
      </div>
    </div>
  );
}

