       return LENIENT_ABHA_ADDRESS.test(cleaned)
         ? undefined
         : t("abha_error_abha_address_invalid");
   }
 }

 export function validateMobile(value: string) {
   return /^\d{10}$/.test(stripSeparators(value))
     ? undefined
     : t("abha_error_mobile_length");
 }

 export function cleanMobile(value: string) {
   return stripSeparators(value);
 }

 export function validateOtp(value: string) {
   return /^\d{6}$/.test(value) ? undefined : t("abha_error_otp_length");
 }

 /** ABDM's rules for a new ABHA address, in the order they are listed. */
 const ABHA_ADDRESS_RULES = [
   "abha_address_rule_length",
   "abha_address_rule_characters",
   "abha_address_rule_one_each",
   "abha_address_rule_ends",
   "abha_address_rule_digit_start",
 ] as const;

 export type AbhaAddressRule = (typeof ABHA_ADDRESS_RULES)[number];

 /** A new ABHA address without its suffix, the way the backend expects it. */
 export function cleanNewAbhaAddress(value: string, suffix: string) {
   const address = value.trim().toLowerCase();
   const ending = `@${suffix}`;
   return suffix && address.endsWith(ending)
     ? address.slice(0, -ending.length)
     : address;
 }

 /** Which of ABDM's rules a new ABHA address keeps, in the order they are listed. */
 export function checkNewAbhaAddress(value: string, suffix: string) {
   const address = cleanNewAbhaAddress(value, suffix);
   const count = (character: string) => address.split(character).length - 1;
   const passes: Record<AbhaAddressRule, boolean> = {
     abha_address_rule_length: address.length >= 8 && address.length <= 18,
     abha_address_rule_characters: /^[a-z0-9._]+$/.test(address),
     abha_address_rule_one_each: count(".") <= 1 && count("_") <= 1,
     abha_address_rule_ends: !/^[._]/.test(address) && !/[._]$/.test(address),
     abha_address_rule_digit_start: !/^\d/.test(address),
   };
   return ABHA_ADDRESS_RULES.map((rule) => ({ rule, passes: passes[rule] }));
 }

 export function validateNewAbhaAddress(
   value: string,
   suffix: string,
 ): string | undefined {
   const failed = checkNewAbhaAddress(value, suffix).find(
     (check) => !check.passes,
   );
   return failed ? t(failed.rule) : undefined;
 }

 /** A 10 digit Indian mobile from an E.164 phone number, if it is one. */
 export function indianMobile(phoneNumber?: string | null) {
   const match = /^\+91(\d{10})$/.exec((phoneNumber ?? "").replace(/\s/g, ""));
   return match ? match[1] : "";
 }

 /** ABDM sends photos as bare base64; the type is read from the magic bytes. */
 export function abhaPhotoUrl(photo?: string | null) {
   if (!photo) {
     return undefined;
   }
   if (photo.startsWith("data:")) {
     return photo;
   }
   const type = photo.startsWith("iVBOR") ? "image/png" : "image/jpeg";
   return `data:${type};base64,${photo}`;
 }

 /** The language the consent text was shown in, recorded with the consent. */
 export function consentLanguage() {
   const language = i18n.language || "en";
   return i18n.exists("abha_consent_text", {
     lng: language,
     fallbackLng: false,
   })
     ? language
     : "en";
 }

