const [suppressDuplicateWarning, setSuppressDuplicateWarning] =
  useState(!!patientId);

const abdm = useAbdmConfig();
const showAbha = !patientId && abdm.enabled;
// The verified ABHA the patient is being registered with, and the form
// values its profile filled in.
const [abha, setAbha] = useState<AbhaJourney | null>(null);
const [abhaValues, setAbhaValues] = useState<AbhaFilledValues>({});

const duplicatePatients = patientPhoneSearch.data?.results.filter(
  (p) => p.id !== patientId,
);

const useAbha = (journey: AbhaJourney) => {
  const values = journey.profile
    ? getAbhaFormValues(journey.profile, form.getValues())
    : {};
  const options = { shouldDirty: true };
  if (values.date_of_birth) {
    form.setValue("age_or_dob", "dob", options);
  } else if (values.age) {
    form.setValue("age_or_dob", "age", options);
  }
  (Object.keys(values) as AbhaField[]).forEach((key) =>
    form.setValue(key, values[key], options),
  );
  setAbha(journey);
  setAbhaValues(values);
};

// What the ABHA filled in goes with it; what the desk has changed stays.
const removeAbha = () => {
  const current = form.getValues();
  (Object.keys(abhaValues) as AbhaField[]).forEach((key) => {
    if (current[key] === abhaValues[key]) {
      form.resetField(key);
    }
  });
  setAbha(null);
  setAbhaValues({});
};

const { mutate: createPatient, isPending: isCreatingPatient } = useMutation({
  mutationKey: ["create_patient"],
  mutationFn: mutate(patientApi.create),
  onSuccess: async (resp: PatientRead) => {
    toast.success(t("patient_registration_success"));
    if (abha) {
      await callApi(abhaApi.link, {
        body: { transaction_id: abha.transaction_id, patient: resp.id },
        silent: true,
      })
        .then(() => toast.success(t("abha_linked")))
        .catch((error) =>
          toast.error(
            t("abha_link_failed_after_registration", {
              error: parseAbhaErrors(error)[0]?.msg,
            }),
          ),
        );
    }
    // Navigate the user to the patients home page to access the newly created patient

