type PatientFormValues = z.infer<ReturnType<typeof getFormSchema>>;

// The fields an ABHA profile fills in, with those that follow the phone number
// and the address while they are marked the same.
type AbhaField =
  | "name"
  | "gender"
  | "date_of_birth"
  | "age"
  | "phone_number"
  | "emergency_phone_number"
  | "address"
  | "permanent_address"
  | "pincode";

type AbhaFilledValues = Partial<Pick<PatientFormValues, AbhaField>>;

/**
 * The registration values an ABHA profile supplies. Name, sex and date of
 * birth are the verified profile's; the phone number, address and pincode
 * only fill fields the desk has left empty.
 */
const getAbhaFormValues = (
  profile: AbhaProfile,
  current: Pick<
    PatientFormValues,
    | "phone_number"
    | "emergency_phone_number_same_as_phone_number"
    | "address"
    | "permanent_address_same_as_address"
    | "pincode"
  >,
): AbhaFilledValues => {
  const values: AbhaFilledValues = {};
  if (profile.name) {
    values.name = profile.name;
  }
  const gender = GENDERS.find((id) => id === profile.gender);
  if (gender) {
    values.gender = gender;
  }
  if (profile.date_of_birth) {
    values.date_of_birth = profile.date_of_birth;
  } else if (profile.year_of_birth) {
    const age = new Date().getFullYear() - profile.year_of_birth;
    if (age >= 1 && age <= 120) {
      values.age = age;
    }
  }
  if (profile.mobile && !isValidPhoneNumber(current.phone_number || "")) {
    values.phone_number = `+91${profile.mobile}`;
    if (current.emergency_phone_number_same_as_phone_number) {
      values.emergency_phone_number = values.phone_number;
    }
  }
  // ABDM sends the district and state apart from the address, which may
  // already name them.
  const address = [
    profile.address,
    ...[profile.district, profile.state].filter(
      (part) =>
        part && !profile.address.toLowerCase().includes(part.toLowerCase()),
    ),
  ]
    .filter(Boolean)
    .join(", ");
  if (address && !current.address?.trim()) {
    values.address = address;
    if (current.permanent_address_same_as_address) {
      values.permanent_address = address;
    }
  }
  if (/^\d{6}$/.test(profile.pincode) && !current.pincode) {
    values.pincode = Number(profile.pincode);
  }
  return values;
};

/** Whether a field still holds the value the ABHA profile filled in. */
const isFromAbha = (
  values: AbhaFilledValues | undefined,
  field: AbhaField,
  value: unknown,
) => values?.[field] !== undefined && values[field] === value;
