const LENIENT_ABHA_ADDRESS = /^[a-z0-9._-]+(@[a-z0-9._-]+)?$/;

/** The value sent for an identifier, cleaned the way the backend cleans it. */
export function cleanIdentifier(type: AbhaIdentifierType, value: string) {
  if (type === "abha_address") {
    return value.trim().toLowerCase();
  }
  return stripSeparators(value);
}

/**
 * Mirrors the backend's validation so that a malformed value is refused
 * before any request is made.
 */
export function validateIdentifier(
  type: AbhaIdentifierType,
  value: string,
): string | undefined {
  const cleaned = cleanIdentifier(type, value);
  switch (type) {
    case "aadhaar":
      return /^\d{12}$/.test(cleaned)
        ? undefined
        : t("abha_error_aadhaar_length");
    case "mobile":
      return /^\d{10}$/.test(cleaned)
        ? undefined
        : t("abha_error_mobile_length");
    case "abha_number":
      return /^\d{14}$/.test(cleaned)
        ? undefined
        : t("abha_error_abha_number_length");
    case "abha_address":
      return LENIENT_ABHA_ADDRESS.test(cleaned)
        ? undefined
        : t("abha_error_abha_address_invalid");
  }
}

export function validateMobile(value: string) {
  return /^\d{10}$/.test(stripSeparators(value))
    ? undefined
    : t("abha_error_mobile_length");
}

export function cleanMobile(value: string) {
