+    .replace(/[^\p{L}\p{N}]+/gu, " ")
+    .trim();
+
+const formatDate = (date: string) => dayjs(date).format("DD MMM YYYY");
+
+const birthYear = (dateOfBirth?: string | null, yearOfBirth?: number | null) =>
+  dateOfBirth ? Number(dateOfBirth.slice(0, 4)) : yearOfBirth;
+
+/** Where the ABHA's name, sex and birth disagree with the patient's record. */
+function getDifferences(
+  profile: AbhaProfile,
+  patient: PatientRead,
+  t: TFunction,
+): Difference[] {
+  const differences: Difference[] = [];
+  if (
+    profile.name &&
+    normaliseName(profile.name) !== normaliseName(patient.name)
+  ) {
+    differences.push({
+      label: t("name"),
+      abha: profile.name,
+      record: patient.name,
+    });
+  }
+  if (profile.gender && patient.gender && profile.gender !== patient.gender) {
+    differences.push({
+      label: t("sex"),
+      abha: t(`GENDER__${profile.gender}`),
+      record: t(`GENDER__${patient.gender}`),
+    });
+  }
+  if (profile.date_of_birth && patient.date_of_birth) {
+    if (profile.date_of_birth !== patient.date_of_birth.slice(0, 10)) {
+      differences.push({
+        label: t("date_of_birth"),
+        abha: formatDate(profile.date_of_birth),
+        record: formatDate(patient.date_of_birth),
+      });
+    }
+  } else {
+    const abhaYear = birthYear(profile.date_of_birth, profile.year_of_birth);
+    const recordYear = birthYear(patient.date_of_birth, patient.year_of_birth);
+    if (abhaYear && recordYear && abhaYear !== recordYear) {
+      differences.push({
+        label: t("year_of_birth"),
+        abha: String(abhaYear),
+        record: String(recordYear),
+      });
+    }
+  }
+  return differences;
+}
+
+/**
+ * Links a verified ABHA to an existing patient. Details that disagree with
+ * the patient's record are shown before the link is made, since an ABHA
+ * linked to the wrong person routes their records to the wrong patient.
+ */
+export default function AbhaLinkActions({
+  journey,
+  patient,
+  startAgain,
+  onLinked,
+}: AbhaLinkActionsProps) {
+  const { t } = useTranslation();
+  const [errors, setErrors] = useState<AbhaError[]>([]);
+
+  const { mutate: link, isPending } = useMutation({
+    mutationFn: mutate(abhaApi.link, { silent: true }),
+    onSuccess: (response: AbhaLinkResponse) => onLinked(response),
+    onError: (error) => setErrors(parseAbhaErrors(error)),
+  });
+
+  const differences = journey.profile
+    ? getDifferences(journey.profile, patient, t)
+    : [];
+
+  return (
+    <div className="flex flex-col gap-3">
+      {differences.length > 0 && (
+        <Alert className="border-yellow-200 bg-yellow-50">
+          <TriangleAlert className="text-yellow-600" aria-hidden />
+          <AlertTitle className="line-clamp-none text-yellow-900">
+            {t("abha_mismatch_title")}
+          </AlertTitle>
+          <AlertDescription className="text-yellow-900">
+            <p>{t("abha_mismatch_description")}</p>
+            <table className="w-full text-left text-sm">
+              <thead>
+                <tr>
+                  <td />
+                  <th scope="col" className="py-1 pr-3 font-medium">
+                    {t("abha_mismatch_in_abha")}
+                  </th>
+                  <th scope="col" className="py-1 font-medium">
+                    {t("abha_mismatch_in_record")}
+                  </th>
+                </tr>
+              </thead>
+              <tbody>
+                {differences.map((difference) => (
+                  <tr
+                    key={difference.label}
+                    className="border-t border-yellow-200"
+                  >
+                    <th scope="row" className="py-1 pr-3 font-medium">
+                      {difference.label}
+                    </th>
+                    <td className="py-1 pr-3 break-all">{difference.abha}</td>
+                    <td className="py-1 break-all">{difference.record}</td>
+                  </tr>
+                ))}
+              </tbody>
+            </table>
+          </AlertDescription>
+        </Alert>
+      )}
+      <AbhaErrors errors={errors} />
+      <div className="flex flex-wrap justify-end gap-2">
+        {startAgain}
+        <Button
+          type="button"
+          variant="primary"
+          disabled={isPending}
+          onClick={() => {
+            setErrors([]);
+            link({ transaction_id: journey.transaction_id, patient: patient.id });
+          }}
+        >
+          {t(differences.length ? "abha_link_anyway" : "abha_link_to_patient")}
+        </Button>
+      </div>
+    </div>
+  );
+}

