import { useQueryClient } from "@tanstack/react-query";
import { IdCard, Info, Link2 } from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";

import { AbhaLookup } from "@/components/Abdm/AbhaIdentifyStep";
import AbhaJourneyFlow from "@/components/Abdm/AbhaJourneyFlow";
import AbhaLinkActions from "@/components/Abdm/AbhaLinkActions";
import {
  cleanNewAbhaAddress,
  getPatientAbha,
  indianMobile,
} from "@/components/Abdm/utils";

import { PatientRead } from "@/types/emr/patient/patient";

interface AbhaPatientDialogProps {
  patient: PatientRead;
  facilityId?: string;
  suffix: string;
}

/**
 * From a patient's record: finds and links their ABHA when none is linked,
 * and verifies the linked one again to show its card.
 */
export default function AbhaPatientDialog({
  patient,
  facilityId,
  suffix,
}: AbhaPatientDialogProps) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const [open, setOpen] = useState(false);

  const { abhaNumber, abhaAddress } = getPatientAbha(patient);
  const linkedAbha: AbhaLookup | undefined = abhaNumber
    ? { type: "abha_number", value: abhaNumber }
    : abhaAddress
      ? { type: "abha_address", value: cleanNewAbhaAddress(abhaAddress, suffix) }
      : undefined;

  const handleLinked = () => {
    toast.success(t("abha_linked"));
    queryClient.invalidateQueries({ queryKey: ["patient", patient.id] });
    setOpen(false);
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button variant="outline">
          {linkedAbha ? <IdCard aria-hidden /> : <Link2 aria-hidden />}
          {t(linkedAbha ? "abha_verify_to_view_card" : "abha_link")}
        </Button>
      </DialogTrigger>
      <DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-2xl">
        <DialogHeader>
          <DialogTitle>
            {t(linkedAbha ? "abha_verify_title" : "abha_link_title")}
          </DialogTitle>
          <DialogDescription>
            {t(
              linkedAbha ? "abha_verify_description" : "abha_link_description",
              { name: patient.name },
            )}
          </DialogDescription>
        </DialogHeader>
        <AbhaJourneyFlow
          suffix={suffix}
          facilityId={facilityId}
          patientId={patient.id}
          knownMobile={indianMobile(patient.phone_number)}
          linkedAbha={linkedAbha}
          onCancel={() => setOpen(false)}
          renderActions={(journey, startAgain) =>
            linkedAbha ? (
              // A patient has one ABHA, and this is not it.
              <div className="flex flex-col gap-3">
                <Alert>
                  <Info aria-hidden />
                  <AlertDescription>
                    {t("abha_patient_has_another", {
                      abha: abhaNumber || abhaAddress,
                    })}
                  </AlertDescription>
                </Alert>
                <div className="flex flex-wrap justify-end gap-2">
                  {startAgain}
                </div>
              </div>
            ) : (
              <AbhaLinkActions
                journey={journey}
                patient={patient}
                startAgain={startAgain}
                onLinked={handleLinked}
              />
            )
          }
        />
      </DialogContent>
    </Dialog>
  );
}

