import fs from "fs";
import path from "path";
const files = [
  ...fs.readdirSync("src/components/Abdm").map((f) => path.join("src/components/Abdm", f)),
  "src/components/Patient/PatientRegistration.tsx",
  "src/components/Patient/PatientDetailsTab/Demography.tsx",
];
const seen = new Set();
for (const file of files) {
  const src = fs.readFileSync(file, "utf8");
  const re = /\bt\(/g;
  let m;
  while ((m = re.exec(src))) {
    let depth = 0, i = m.index + 1, end = -1;
    for (; i < src.length; i++) {
      if (src[i] === "(") depth++;
      else if (src[i] === ")") { depth--; if (depth === 0) { end = i; break; } }
    }
    const call = src.slice(m.index, end + 1).replace(/\s+/g, " ");
    if (!/abha|patient__abha/.test(call)) continue;
    if (file.endsWith("PatientRegistration.tsx") || file.endsWith("Demography.tsx")) {
      if (!/abha/.test(call)) continue;
    }
    if (seen.has(call)) continue;
    seen.add(call);
    const line = src.slice(0, m.index).split("\n").length;
    console.log(`${path.basename(file)}:${line}  ${call.slice(0, 220)}`);
  }
}
EOF
