const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

/**
 * The ABHA API answers `{"errors": [{type, msg, loc?, ...}]}`; permission
 * refusals answer `{"detail": "..."}`. Every ABHA call is silent, so these are
 * rendered on the step in view rather than as toasts.
 */
export function parseAbhaErrors(
  error: unknown,
  fallback: string = t("abha_request_failed"),
): AbhaError[] {
  if (error instanceof HTTPError) {
    const cause = error.cause;
    const errors = Array.isArray(cause?.errors)
      ? cause.errors.filter(isRecord)
      : [];
    if (errors.length) {
      return errors.map((item) => {
        const loc = Array.isArray(item.loc) ? item.loc : [];
        return {
          type: typeof item.type === "string" ? item.type : "error",
          msg:
            typeof item.msg === "string" && item.msg
              ? item.msg
              : t("abha_request_failed"),
          field: loc.length ? String(loc[0]).split(".")[0] : undefined,
          available_in:
            typeof item.available_in === "number"
              ? item.available_in
              : undefined,
          patient: isRecord(item.patient)
            ? (item.patient as unknown as AbhaPatientSummary)
            : null,
          step:
            typeof item.step === "string"
              ? (item.step as AbhaStep)
              : undefined,
          request_id:
            typeof item.request_id === "string" ? item.request_id : undefined,
        };
      });
    }
    if (typeof cause?.detail === "string") {
      return [{ type: "error", msg: cause.detail }];
    }
    return [{ type: "error", msg: t("abha_request_failed") }];
  }
  if (error instanceof Error && error.message === "Network Error") {
    return [{ type: "network", msg: t("abha_network_error") }];
  }
  return [{ type: "error", msg: fallback }];
}

/**
 * Errors that name a field the step shows go under that field; the rest are
 * shown together at the foot of the step.
 */
export function splitAbhaErrors(errors: AbhaError[], fields: string[]) {
  const fieldErrors: Record<string, string> = {};
  const general: AbhaError[] = [];
  for (const error of errors) {
    if (error.field && fields.includes(error.field)) {
