import { IdCard, Plus } from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";

import AbhaCardDialog from "@/components/Abdm/AbhaCardDialog";
import AbhaJourneyFlow from "@/components/Abdm/AbhaJourneyFlow";

import { AbhaJourney } from "@/types/abdm/abha";

interface AbhaRegistrationPanelProps {
  suffix: string;
  facilityId?: string;
  knownMobile?: string;
  // The verified ABHA the new patient will be registered with.
  abha: AbhaJourney | null;
  onUse: (journey: AbhaJourney) => void;
  onRemove: () => void;
}

/**
 * Registration starts from the person's ABHA when they have one: it is found
 * or created here, fills the form below, and is linked to the patient once the
 * registration is saved.
 */
export default function AbhaRegistrationPanel({
  suffix,
  facilityId,
  knownMobile,
  abha,
  onUse,
  onRemove,
}: AbhaRegistrationPanelProps) {
  const { t } = useTranslation();
  const [open, setOpen] = useState(true);
  const [cardOpen, setCardOpen] = useState(false);

  const heading = (
    <div className="flex flex-col gap-1">
      <h5 className="text-lg font-semibold">{t("abha_full_name")}</h5>
      <p className="text-sm text-gray-700">
        {t("abha_registration_description")}
      </p>
    </div>
  );

  if (abha) {
    return (
      <section
        aria-label={t("abha_full_name")}
        className="flex flex-col gap-4 rounded-md bg-white p-6 shadow"
      >
        <div className="flex flex-col gap-1">
          <h5 className="text-lg font-semibold">{t("abha_full_name")}</h5>
          <p className="text-sm text-gray-700">
            {t("abha_will_be_linked_on_registration")}
          </p>
        </div>
        <dl className="grid gap-3 rounded-md border border-primary-200 bg-primary-50 p-4 sm:grid-cols-2">
          <div className="flex flex-col">
            <dt className="text-xs text-gray-500">{t("abha_number")}</dt>
            <dd className="text-sm font-medium break-all text-gray-900">
              {abha.abha_number || "-"}
            </dd>
          </div>
          <div className="flex flex-col">
            <dt className="text-xs text-gray-500">{t("abha_address")}</dt>
            <dd className="text-sm font-medium break-all text-gray-900">
              {abha.abha_address || "-"}
            </dd>
          </div>
        </dl>
        <div className="flex flex-wrap justify-end gap-2">
          <Button
            type="button"
            variant="ghost"
            onClick={() => {
              setOpen(false);
              onRemove();
            }}
          >
            {t("abha_remove")}
          </Button>
          <Button
            type="button"
            variant="outline"
            onClick={() => setCardOpen(true)}
          >
            <IdCard aria-hidden />
            {t("abha_view_card")}
          </Button>
        </div>
        <AbhaCardDialog
          transactionId={abha.transaction_id}
          open={cardOpen}
          onOpenChange={setCardOpen}
        />
      </section>
    );
  }

  if (!open) {
    return (
      <section
        aria-label={t("abha_full_name")}
        className="flex flex-wrap items-center justify-between gap-3 rounded-md bg-white p-4 shadow"
      >
        <p className="text-sm text-gray-700">{t("abha_add_later_hint")}</p>
        <Button type="button" variant="outline" onClick={() => setOpen(true)}>
          <Plus aria-hidden />
          {t("abha_add")}
        </Button>
      </section>
    );
  }

  return (
    <section
      aria-label={t("abha_full_name")}
      className="flex flex-col gap-4 rounded-md bg-white p-6 shadow"
    >
      {heading}
      <AbhaJourneyFlow
        suffix={suffix}
        facilityId={facilityId}
        knownMobile={knownMobile}
        onCancel={() => setOpen(false)}
        renderActions={(journey, startAgain) => (
          <div className="flex flex-wrap justify-end gap-2">
            {startAgain}
            <Button
              type="button"
              variant="primary"
              onClick={() => onUse(journey)}
            >
              {t("abha_use_for_registration")}
            </Button>
          </div>
        )}
      />
    </section>
  );
}

