import { useMutation } from "@tanstack/react-query";
import { SearchX } from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";

import AbhaErrors from "@/components/Abdm/AbhaErrors";
import { AbhaLookup } from "@/components/Abdm/AbhaIdentifyStep";
import { AbhaError } from "@/components/Abdm/utils";

import { AbhaJourney } from "@/types/abdm/abha";
import abhaApi from "@/types/abdm/abhaApi";
import mutate from "@/Utils/request/mutate";

interface AbhaNotFoundStepProps {
  // Absent when an ABHA address search found nothing: no session is opened
  // for a search.
  journey: AbhaJourney | null;
  lookup: AbhaLookup;
  onJourney: (journey: AbhaJourney) => void;
  onError: (error: unknown) => AbhaError[];
  onCreateWithAadhaar: () => void;
  onTryAnother: () => void;
}

/**
 * ABDM has said nobody holds an ABHA for what was entered. An ABHA is made
 * from an Aadhaar number, so creation follows directly only from an Aadhaar
 * lookup; any other lookup leads to one, which finds an existing ABHA first.
 */
export default function AbhaNotFoundStep({
  journey,
  lookup,
  onJourney,
  onError,
  onCreateWithAadhaar,
  onTryAnother,
}: AbhaNotFoundStepProps) {
  const { t } = useTranslation();
  const [errors, setErrors] = useState<AbhaError[]>([]);
  const createAllowed = !!journey?.create_allowed;

  const { mutate: sendEnrolOtp, isPending } = useMutation({
    mutationFn: mutate(abhaApi.createSendOtp, { silent: true }),
    onSuccess: onJourney,
    onError: (error) => setErrors(onError(error)),
  });

  return (
    <div className="flex flex-col gap-5">
      <div className="flex items-start gap-3">
        <SearchX className="mt-0.5 size-5 shrink-0 text-gray-500" aria-hidden />
        <div className="flex flex-col gap-1">
          <p className="text-base font-semibold text-gray-900">
            {t("abha_not_found_title")}
          </p>
          <p className="text-sm text-gray-700">
            {t(`abha_not_found__${lookup.type}`, { address: lookup.value })}
          </p>
          <p className="text-sm text-gray-700">
            {t(
              createAllowed
                ? "abha_not_found_create_now"
                : "abha_not_found_create_with_aadhaar",
            )}
          </p>
        </div>
      </div>

      <AbhaErrors errors={errors} />

      <div className="flex flex-wrap justify-end gap-2">
        <Button
          type="button"
          variant="ghost"
          onClick={onTryAnother}
          disabled={isPending}
        >
          {t("abha_try_another_identifier")}
        </Button>
        {createAllowed && journey ? (
          <Button
            type="button"
            variant="primary"
            onClick={() =>
              sendEnrolOtp({ transaction_id: journey.transaction_id })
            }
            disabled={isPending}
          >
            {t("abha_create")}
          </Button>
        ) : (
          <Button type="button" variant="primary" onClick={onCreateWithAadhaar}>
            {t("abha_create_with_aadhaar")}
          </Button>
        )}
      </div>
    </div>
  );
}

