import { ReactNode, useEffect, useRef, useState } from "react";
import { useTranslation } from "react-i18next";

import AbhaAccountChooser from "@/components/Abdm/AbhaAccountChooser";
import AbhaAddressStep from "@/components/Abdm/AbhaAddressStep";
import AbhaIdentifyStep, { AbhaLookup } from "@/components/Abdm/AbhaIdentifyStep";
import AbhaMobileVerifyStep from "@/components/Abdm/AbhaMobileVerifyStep";
import AbhaNotFoundStep from "@/components/Abdm/AbhaNotFoundStep";
import AbhaOtpStep, { AbhaMobileSuggestion } from "@/components/Abdm/AbhaOtpStep";
import AbhaVerifiedStep from "@/components/Abdm/AbhaVerifiedStep";
import {
  AbhaError,
  cleanIdentifier,
  parseAbhaErrors,
} from "@/components/Abdm/utils";

import { AbhaJourney } from "@/types/abdm/abha";
import abhaApi from "@/types/abdm/abhaApi";
import { callApi } from "@/Utils/request/query";
import { HTTPError } from "@/Utils/request/types";

interface AbhaJourneyFlowProps {
  suffix: string;
  facilityId?: string;
  // The patient the ABHA is for; absent while registering a new patient.
  patientId?: string;
  // A 10 digit mobile CARE already holds for the person.
  knownMobile?: string;
  // The ABHA already linked to the patient, which the search starts from.
  linkedAbha?: AbhaLookup;
  // The footer for a verified ABHA that is not linked to any patient.
  renderActions: (journey: AbhaJourney, startAgain: ReactNode) => ReactNode;
  onCancel?: () => void;
}

interface Start {
  key: number;
  lookup: AbhaLookup;
  notice?: string;
}

/**
 * Finds the person's ABHA, or creates one, and verifies it with an OTP. Only
 * the step the journey is at is shown; the backend holds the journey, so a
 * step that is out of date is brought back in line with it.
 */
export default function AbhaJourneyFlow({
  suffix,
  facilityId,
  patientId,
  knownMobile,
  linkedAbha,
  renderActions,
  onCancel,
}: AbhaJourneyFlowProps) {
  const { t } = useTranslation();
  const [journey, setJourney] = useState<AbhaJourney | null>(null);
  // What CARE already holds for the person is where the search starts, so it
  // is never asked for again.
  const [start, setStart] = useState<Start>(() => ({
    key: 0,
    lookup:
      linkedAbha ??
      (knownMobile
        ? { type: "mobile", value: knownMobile }
        : { type: "aadhaar", value: "" }),
  }));
  const [lookup, setLookup] = useState<AbhaLookup | null>(null);
  const [lookupMobile, setLookupMobile] = useState("");
  const [addressNotFound, setAddressNotFound] = useState<AbhaLookup | null>(
    null,
  );

  const restart = (notice?: string, next?: AbhaLookup) => {
    const type = next?.type ?? lookup?.type ?? "aadhaar";
    setJourney(null);
    setAddressNotFound(null);
    setStart((previous) => ({
      key: previous.key + 1,
      // An Aadhaar number is not carried over: it is entered afresh each time.
      lookup: next ?? {
        type,
        value: type === "aadhaar" ? "" : (lookup?.value ?? ""),
      },
      notice,
    }));
  };

  const resync = (transactionId: string) => {
    callApi(abhaApi.state, {
      queryParams: { transaction_id: transactionId },
      silent: true,
    })
      .then(setJourney)
      .catch((error) => restart(parseAbhaErrors(error)[0]?.msg));
  };

  const handleError = (error: unknown): AbhaError[] => {
    const errors = parseAbhaErrors(error);
